INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('accessoire-aleatoire', 1, 'Accessoire aléatoire', 'Accessoire vierge de tout effet apparent ; son pouvoir ne se révèle qu’une fois porté, sauf pour un bijoutier capable d’en identifier la propriété.', 'monstres', 'Bestiaire 2.0 › ligne 28420');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('armure-funeraire', 2, 'Armure funéraire', 'Armure portée par les momies chargées de défendre les tombeaux ; il s’agit d’une armure intermédiaire que seuls les êtres liés à la magie de l’Espace/Temps peuvent revêtir.', 'monstres', 'Bestiaire 2.0 › ligne 28421');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('bandelette-de-momie', 3, 'Bandelette de momie', 'Bandelettes de lin imprégnées d’un parfum floral ancien ; en assembler six sur une armure complète lui confère +2 à l’initiative ainsi qu’une meilleure résistance à la fatigue.', 'monstres', 'Bestiaire 2.0 › ligne 28422');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('cabosse', 4, 'Cabosse', 'Fruit de la Terre, utilisé comme ingrédient alchimique pour des préparations liées à la défense physique.', 'monstres', 'Bestiaire 2.0 › ligne 28423');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('chair-rouge', 5, 'Chair rouge', 'Chair provenant d’une créature profondément liée à la magie du Feu. Elle possède les mêmes usages que les fruits dans la fabrication de fioles, mais peut également servir dans certains philtres.', 'monstres', 'Bestiaire 2.0 › ligne 28424');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('chapeau-de-meduse', 6, 'Chapeau de méduse', 'Restes gélatineux du chapeau d’une méduse, utilisés en alchimie liée à l’Eau.', 'monstres', 'Bestiaire 2.0 › ligne 28425');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('citron', 7, 'Citron', 'Fruit de la Foudre, ingrédient alchimique employé dans des mixtures liées à la barrière.', 'monstres', 'Bestiaire 2.0 › ligne 28426');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('c-ur-polaire', 8, 'Cœur polaire', 'Noyau cyan ayant contenu la puissance d’un élémentaire de la Glace, désormais inactif ; agit comme amplificateur majeur en alchimie.', 'monstres', 'Bestiaire 2.0 › ligne 28427');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('c-ur-abyssal', 9, 'Cœur abyssal', 'Noyau bleu ayant contenu la puissance d’un élémentaire de l’Eau, désormais inactif ; utilisé comme amplificateur majeur en alchimie.', 'monstres', 'Bestiaire 2.0 › ligne 28428');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('c-ur-sanglant', 10, 'Cœur sanglant', 'Noyau bordeaux ayant contenu la puissance d’un élémentaire du Sang, désormais inactif ; utilisé comme amplificateur majeur en alchimie.', 'monstres', 'Bestiaire 2.0 › ligne 28429');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('c-ur-sterile', 11, 'Cœur stérile', 'Noyau blanc ayant contenu la puissance d’un élémentaire du Vide, désormais inactif ; utilisé comme amplificateur majeur en alchimie.', 'monstres', 'Bestiaire 2.0 › ligne 28430');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('c-ur-terrestre', 12, 'Cœur terrestre', 'Noyau brun ayant contenu la puissance d’un élémentaire de la Terre, désormais inactif ; utilisé comme amplificateur majeur en alchimie.', 'monstres', 'Bestiaire 2.0 › ligne 28431');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('c-ur-tenebreux', 13, 'Cœur ténébreux', 'Noyau violet ayant contenu la puissance d’un élémentaire de l’Ombre, désormais inactif ; utilisé comme amplificateur majeur en alchimie.', 'monstres', 'Bestiaire 2.0 › ligne 28432');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('corossol', 14, 'Corossol', 'Fruit de la Nécromancie, ingrédient alchimique utilisé dans des préparations liées à la mort et aux soins des morts vivants.', 'monstres', 'Bestiaire 2.0 › ligne 28433');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('cristal-de-brume-blanche', 15, 'Cristal de brume blanche', 'Cristal renfermant la puissance d’un crachin blanc sous forme de brume condensée ; utilisé en alchimie.', 'monstres', 'Bestiaire 2.0 › ligne 28434');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('cristal-de-souffle-boreal', 16, 'Cristal de souffle boréal', 'Petit cristal en forme de dodécaèdre emprisonnant du vent froid dans un bloc de glace. Utilisé en alchimie avancée et dans la fabrication de remèdes contre certaines maladies.', 'monstres', 'Bestiaire 2.0 › ligne 28435');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('eau-fondue-du-premier-givre', 17, 'Eau fondue du premier givre', 'Eau d’une pureté exceptionnelle obtenue lors de la transition entre l’hiver et le printemps ; agit comme catalyseur en alchimie.', 'monstres', 'Bestiaire 2.0 › ligne 28436');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('fragment-de-piece-elementaire', 18, 'Fragment de pièce élémentaire', 'Morceau d’une pièce élémentaire brisée. 16 fragments sont nécessaires pour reconstituer une pièce complète.', 'monstres', 'Bestiaire 2.0 › ligne 28437');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('fraise', 19, 'Fraise', 'Fruit du Feu, ingrédient alchimique servant aux concoctions liées à la santé.', 'monstres', 'Bestiaire 2.0 › ligne 28438');
