INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/archidemon#carte:archidemon-superieur', 11, 'capacites', 'Capacité(s)', 'Haine mutuelle. Cette créature inflige un bonus +10 dégâts contre les Majins mais ces derniers ont également le même bonus sur cette première.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/archidemon#carte:archidemon-superieur', 12, 'tactique', 'TACTIQUE COMBAT', 'Le supérieur en plus d’être plus fort possède une réserve de nuage bien plus grande que les normaux, ce qui lui permet d’augmenter encore plus sa puissance.', 'Bestiaire 2.0 › ligne 1222', 'monstres');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 1, NULL, NULL, 'Haine mutuelle', 'Cette créature inflige un bonus +10 dégâts contre les Majins mais ces derniers ont également le même bonus sur cette première.', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 2, NULL, NULL, 'Magie aléatoire', 'Cette créature commence avec une ou deux magie(s) aléatoire(s), le mj le détermine au dé (ou bien de lui-même). Elle peut lancer des sorts selon son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 3, NULL, NULL, 'Produit du Nuage', 'Cette créature produit une sorte de nuage de kcirevam en permanence quand il est en stress. Chaque attaque qu’il prend et chaque tour de jeu terminée, il obtient 2 compteurs de Nuage. Il gagne +4 aux dégâts tous les 10 compteurs (pour un maximum de 30).', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 4, NULL, NULL, 'Nuage déterminant', 'Si 10 compteurs de Nuage = +5% à tous les jets de dés.', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 5, '[EP2]', 2, 'Élément contrôlé', 'L’attaque de cette créature peut taper dans deux éléments à la fois, aucun élément, un seul à la fois et ceux à volonté.', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 6, '[EP3]', 3, 'Nuage rapide', 'Si 15 compteurs de Nuage = +1 Vitesse', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 7, '[EP4]', 4, 'Renfermement', 'Soigne de 2d6 santé à chaque début de tour.', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 8, '[EP5]', 5, 'Nuage maudit', 'Si 20 compteurs de Nuage = Les attaques de la créature impose l’effet du sort d’ombre “malédiction” pendant 1 tour.', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 9, '[EP6]', 6, 'Aura de peur', 'Inflige un malus de -10% au jet de défense aux ennemis à deux cases.', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 10, '[EP7]', 7, 'Nuage colérique', 'Si 30 compteurs de Nuage = Peut sacrifié 3IC pour une attaque supplémentaire (1 fois/combat)', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 11, '[EP8]', 8, 'Explosion nuageuse', 'Capable de libérer le nuage en une grosse explosion sur tout le terrain. Inflige 1d4 multiplié par le nombre de compteurs consommés. Inflige un contre coup qui correspond à la moitié des dégâts infligés. Réussir un jet de défense divise par 2 les dégâts réussi mais ne les annule pas.', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 12, '[EP9]', 9, 'Élasticité', 'La portée des attaques augmente de 2.', 'monstres', 'Bestiaire 2.0 › ligne 1182');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/archidemon#carte:archidemon-superieur', 13, '[EP10]', 10, 'Grande réserve', 'La réserve de Nuage augmente à 40.', 'monstres', 'Bestiaire 2.0 › ligne 1182');
