INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-beige#carte:blob-de-la-lumiere', 1, NULL, NULL, 'Inerte', 'Amplifie la Volonté à 10, ce qui permet d’être immunisé au jet de volonté (sauf contre les altérations d’état faible où un jet se fait avec un malus de 30).', 'monstres', 'Bestiaire 2.0 › ligne 1597');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-beige#carte:blob-de-la-lumiere', 2, NULL, NULL, 'Gluant', 'Cette créature est faite dans une matière gélatineuse, ce qui lui permet d’être résistante face au dégâts de frappe. Sa structure lui inflige une faiblesse contre la paralysie.', 'monstres', 'Bestiaire 2.0 › ligne 1597');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-beige#carte:blob-de-la-lumiere', 3, NULL, NULL, 'Tome de la Lumière lvl1', 'Permet à cette créature de lancer des sorts de la magie de la Lumière au niveau 1 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 1597');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-beige#carte:blob-de-la-lumiere', 4, NULL, NULL, 'Élément Lumière', 'L’arme de cette créature possède 30% de chance d’obliger un jet de vigueur à l’adversaire pour ne pas qu’il prenne “aveuglement 1”. L’arme peut taper dans l’élément associé et ses sorts de la lumière infligent également un bonus de +3 aux dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 1597');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-beige#carte:blob-de-la-lumiere', 5, NULL, NULL, 'Dynamo', 'Cette créature brille si fort que tous les jets offensifs dirigés contre elle ont un malus de 10% à la réussite.', 'monstres', 'Bestiaire 2.0 › ligne 1597');
