INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/blob-bleu', 'Blob bleu', 'blob-bleu', 6, 'B', 'EP1', 1, 1, 'Le Blob bleu est apprécié pour sa belle couleur, on le retrouve près des lacs ou de la mer. Sa chair bleue est indispensable pour la fiole bleue qui redonne chakra. Sa gelée est également un terrain idéal pour la pousse de certaines plantes liées à l’eau comme par exemple le prunier.', 'Plage, Lac, Marais', NULL, 'monstres', 'Bestiaire 2.0 › lignes 1927-2169');
