INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/blob-bleu#carte:blob-bleu', 11, 'tactique', 'TACTIQUE COMBAT', 'Malgré leur aspect gélatineux et primitif, ces créatures sont capables de lancer les sorts les plus basiques de la magie de l’eau. Ils voient ceux qui sont faibles contre eux comme des proies et vont s''acharner sur eux quand ils le peuvent. Si des ennemis possèdent des magies efficaces sur lui, il va garder ses distances avec eux.', 'Bestiaire 2.0 › ligne 1984', 'monstres');
