INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-bleu#carte:blob-prune', 1, NULL, NULL, 'Inerte', 'Amplifie la Volonté à 10, ce qui permet d’être immunisé au jet de volonté (sauf contre les altérations d’état faible où un jet se fait avec un malus de 30).', 'monstres', 'Bestiaire 2.0 › ligne 2030');
