INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-brun#carte:blob-de-la-terre', 1, NULL, NULL, 'Inerte', 'Amplifie la Volonté à 10, ce qui permet d’être immunisé au jet de volonté (sauf contre les altérations d’état faible où un jet se fait avec un malus de 30).', 'monstres', 'Bestiaire 2.0 › ligne 2581');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-brun#carte:blob-de-la-terre', 2, NULL, NULL, 'Gluant', 'Cette créature est faite dans une matière gélatineuse, ce qui lui permet d’être résistante face au dégâts de frappe. Sa structure lui inflige une faiblesse contre la paralysie.', 'monstres', 'Bestiaire 2.0 › ligne 2581');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-brun#carte:blob-de-la-terre', 3, NULL, NULL, 'Tome de la Terre lvl1', 'Permet à cette créature de lancer des sorts de la magie de la Terre au niveau 1 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 2581');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-brun#carte:blob-de-la-terre', 4, NULL, NULL, 'Élément Terre', 'L’arme de cette créature possède 30% de chance d’obliger un jet de vigueur à l’adversaire pour ne pas qu’il prenne “pétrifié 1”. L’arme peut taper dans l’élément associé et ses sorts de terre infligent également un bonus de +3 aux dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 2581');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-brun#carte:blob-de-la-terre', 5, NULL, NULL, 'Égide', 'Permet de survivre à 1 santé contre une attaque qui est censée vous mettre dans le coma. Marche qu’une fois.', 'monstres', 'Bestiaire 2.0 › ligne 2581');
