INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-mauve#carte:blob-de-lombre', 1, NULL, NULL, 'Inerte', 'Amplifie la Volonté à 10, ce qui permet d’être immunisé au jet de volonté (sauf contre les altérations d’état faible où un jet se fait avec un malus de 30).', 'monstres', 'Bestiaire 2.0 › ligne 3317');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-mauve#carte:blob-de-lombre', 2, NULL, NULL, 'Gluant', 'Cette créature est faite dans une matière gélatineuse, ce qui lui permet d’être résistante face au dégâts de frappe. Sa structure lui inflige une faiblesse contre la paralysie.', 'monstres', 'Bestiaire 2.0 › ligne 3317');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-mauve#carte:blob-de-lombre', 3, NULL, NULL, 'Tome de l’Ombre lvl1', 'Permet à cette créature de lancer des sorts de la magie de l’Ombre au niveau 1 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 3317');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-mauve#carte:blob-de-lombre', 4, NULL, NULL, 'Élément Ombre', 'L’arme de cette créature possède 30% de chance d’obliger un jet de fermeté à l’adversaire pour ne pas qu’il prenne “peur 1”. L’arme peut taper dans l’élément associé et ses sorts de l’ombre infligent également un bonus de +3 aux dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 3317');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-mauve#carte:blob-de-lombre', 5, NULL, NULL, 'Sournois', 'Quand l’adversaire n’est pas attentif à l’attaquant, permet d’infliger un bonus de 2d4 dégâts en plus des dégâts de l’arme.', 'monstres', 'Bestiaire 2.0 › ligne 3317');
