INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/blob-metallique#carte:blob-metallique', 14, 'tactique', 'TACTIQUE COMBAT', 'Ce blob très particulier est à la base une création alchimique qui est faite de différents métaux et est plus ou moins fort selon lequel il est relié. Connaître les différents métaux est une bonne chose pour estimer leur potentiel défensif.', 'Bestiaire 2.0 › ligne 3515', 'monstres');
