INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/blob-noir', 'Blob noir', 'blob-noir', 13, 'B', 'EP1', 1, 1, 'Ce Blob est de couleur noire marbrée de teintes de gris asphalte. On retrouve principalement cette créature dans les marécages ou autre zones où la corruption a polluée certaines terres. Sa chair émet une forte quantité de corruption, il est donc très déconseillé de le toucher à main nues sous peine de graves atteintes au lobe chakratique.', 'Marais', NULL, 'monstres', 'Bestiaire 2.0 › lignes 3809-4054');
