INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-transparent#carte:blob-du-vide', 3, NULL, NULL, 'Tome du Vide lvl1', 'Permet à cette créature de lancer des sorts de la magie du Vide au niveau 1 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 4220');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-transparent#carte:blob-du-vide', 4, NULL, NULL, 'Élément Vide', 'L’arme de cette créature possède 30% de chance d’obliger un jet de fermeté à l’adversaire pour ne pas qu’il prenne “enragé 1”. L’arme peut taper dans l’élément associé et ses sorts de vide infligent également un bonus de +3 aux dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 4220');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/blob-transparent#carte:blob-du-vide', 5, NULL, NULL, 'Anti-magie', 'Cette créature est totalement immunisée à la magie.', 'monstres', 'Bestiaire 2.0 › ligne 4220');
