INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/carcalanche#carte:carcalanche-du-froid', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 5532');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/carcalanche#carte:carcalanche-du-froid', 2, NULL, NULL, 'Souffle élémentaire', 'Cette créature est capable de cracher un souffle lié à son élément. Ce souffle est capable d''infliger l''altération d''état lié à l''élément à hauteur de 35% de chance de l''infliger. (les joueurs doivent faire les jets en conséquences pour ne pas prendre l''altération d''état)', 'monstres', 'Bestiaire 2.0 › ligne 5532');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/carcalanche#carte:carcalanche-du-froid', 3, NULL, NULL, 'Fragilité tranchante', 'Chaque fois qu’il subit une attaque physique au cac, des éclats de glace sèche sont projetés autour de lui (2d6 dégâts).', 'monstres', 'Bestiaire 2.0 › ligne 5532');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/carcalanche#carte:carcalanche-du-froid', 4, NULL, NULL, 'Craquellement', 'Les armes qui le frappent directement et qui font 91 ou plus à leur jet perdent un cran de solidité.', 'monstres', 'Bestiaire 2.0 › ligne 5532');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/carcalanche#carte:carcalanche-du-froid', 5, NULL, NULL, 'Météo sournoise', 'Tant que cette créature est dans une météo qui avantage sa magie, il est capable de faire des dégâts sournois à hauteur de 2d4.', 'monstres', 'Bestiaire 2.0 › ligne 5532');
