INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/casque-brise', 'Casque brisé', 'casque-brise', 21, 'C', 'EP2', 2, 2, 'Le Casque Brisé est une apparition silencieuse, composée d’un vieux casque fendu, ébréché, dont les plaques déformées laissent deviner l’impact qui l’a détruit autrefois. De l’intérieur s’échappe un spectre d’un vert sombre, plus léger et plus discret que ses compagnons. Ses contours sont flous, presque translucides, comme si le fantôme lui-même hésitait entre se manifester ou disparaître. Deux lueurs pâles brillent derrière la visière brisée, donnant l’impression d’yeux en observation perpétuelle.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/casque-brise', 1, 'Ruines', 'ruines', 'monstres', 'Bestiaire 2.0 › lignes 5744-5804');
