INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/cerbere', 'Cerbère', 'cerbere', 22, 'C', 'EP5', 5, 5, 'Gardiens abominables des lieux sacrés, ce canidé à trois tête reste et restera fidèle aux ordres de son maître quel qu''ils soient et ces ordres seront probablement pour récupérer votre tête sur votre cadavre en charpie. Ses trois têtes agissent comme un trio de musiciens, accordé et déterminé à vous détruire. Celle de gauche est la plus agressive et violente, celle de droite, elle, est plus réfléchie et sait utiliser des sorts de quatre éléments différents et enfin celle du centre est l''égide des deux autres à laquelle il ne faut pas s''y frotter. Montrez vous plus intelligents que ce chien infernal et peut-être, vous survivrez.', 'Gardien de porte, forêts, plaines, ruines', NULL, 'monstres', 'Bestiaire 2.0 › lignes 5809-6034');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/cerbere', 1, 'Gardien de porte', 'gardien-de-porte', 'monstres', 'Bestiaire 2.0 › lignes 5809-6034');
