INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/charcabe#carte:charcabe-brule', 9, 'immunite', 'Immunité(s) Dégâts/Effets = 0', 'Poison, Maladie, Couardise, Peur, Fatigue, Brûlure', 'Bestiaire 2.0 › ligne 6079', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/charcabe#carte:charcabe-brule', 10, 'capacites', 'Capacité(s)', 'Non-Mort. Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/charcabe#carte:charcabe-brule', 11, 'tactique', 'TACTIQUE COMBAT', 'Ces zombis de feu se battent comme le font les mages rouges, charge un sort et l’utilise avec leur prochaine attaque avec leur arme. Leur volonté très élevé fait qu’ils ratent très rarement leur sort mais étrangement il ne lance jamais leur sort comme ça, ils chargent toujours leur sort.', 'Bestiaire 2.0 › ligne 6096', 'monstres');
