INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/charcabe#carte:charcabe-brule', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 6083');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/charcabe#carte:charcabe-brule', 2, NULL, NULL, 'Lanceur de sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Boule de feu, Souffle chaud.', 'monstres', 'Bestiaire 2.0 › ligne 6083');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/charcabe#carte:charcabe-brule', 3, NULL, NULL, 'Concentration coloré', 'Utilise la concentration au lieu de la magie pour lancer ses sorts.', 'monstres', 'Bestiaire 2.0 › ligne 6083');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/charcabe#carte:charcabe-brule', 4, NULL, NULL, 'Chargement contact', 'Permet de charger un sort d''attaque lvl1 ou lvl2 le premier tour et de l''utiliser en même temps que l''attaque de contact le tour suivant.', 'monstres', 'Bestiaire 2.0 › ligne 6083');
