INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/cheval-unicorne#carte:cheval-unicorne-dore', 11, 'tactique', 'TACTIQUE COMBAT', 'La corne et les sabots parfaitement dorés sont capables d’infliger les pires souffrances contre les démons. Ces majestueux chevaux ont un caractère bien trempé et il semble quasi impossible de les dompter. On entend souvent des légendes concernant des grands noms des temples de la lumière et de l’eau qui auraient réussi à les monter.', 'Bestiaire 2.0 › ligne 6673', 'monstres');
