INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/collecteur#carte:collecteur', 12, 'immunite', 'Immunité(s) Dégâts/Effets = 0', 'Poison, Maladie, Enragé, Peur, Aveuglement, Fatigue, Saignement, Surdité, Estoc', 'Bestiaire 2.0 › ligne 6761', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/collecteur#carte:collecteur', 13, 'capacites', 'Capacité(s)', 'Non-Mort. Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/collecteur#carte:collecteur', 14, 'tactique', 'TACTIQUE COMBAT', 'Ce monstre à beau être lent, il possède beaucoup de puissance, sa nature squelettique fait qu’il n’a pas à s’inquiéter de ceux qui utilise des projectile et son lien avec la terre fait qu’il n’est pas vulnérable aux dégâts de frappe. Il avancera vers l’ennemi le plus proche, le détruira de toutes ses forces pour avoir l’occasion d’assimiler ses ossements.', 'Bestiaire 2.0 › ligne 6790', 'monstres');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 6765');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur', 2, NULL, NULL, 'Squelettique', 'Rend cette créature immunisée aux attaques d’estoc.', 'monstres', 'Bestiaire 2.0 › ligne 6765');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur', 3, NULL, NULL, 'Être de la Terre', 'Cette créature est capable de lancer des sorts de son niveau de puissance magique.', 'monstres', 'Bestiaire 2.0 › ligne 6765');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur', 4, NULL, NULL, 'Être de la Nécromancie', 'Cette créature est capable de lancer des sorts de son niveau de puissance magique.', 'monstres', 'Bestiaire 2.0 › ligne 6765');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur', 5, '[EP3]', 3, 'Force démesurée', 'Cette créature peut dépasser la limite de Force de 1.', 'monstres', 'Bestiaire 2.0 › ligne 6765');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur', 6, '[EP4]', 4, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 6765');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur', 7, '[EP5]', 5, 'Statue', 'Si la créature n’a pas bougé durant ce tour, elle gagne +5AP mais perd 6 INI, et ceux jusqu''au début de son prochain tour.', 'monstres', 'Bestiaire 2.0 › ligne 6765');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/collecteur#carte:collecteur', 8, '[EP6]', 6, 'Racine', 'Si la créature n’a pas bougé durant ce tour, elle récupère 5% de sa santé max.', 'monstres', 'Bestiaire 2.0 › ligne 6765');
