INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/corbeau-agressif#carte:corbeau-agressif-noir', 1, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 7073');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/corbeau-agressif#carte:corbeau-agressif-noir', 2, NULL, NULL, 'Regard infernal', 'Cette créature est non seulement capable de forcer le jet de vigueur à toutes les cibles qu’elle voit pour ne pas qu’elle prenne brûlure 1, mais elle peut aussi aggraver la brûlure jusqu’au stade 2 si elle touche avec son arme une victime de brûlure. (Action 1 fois par combat)', 'monstres', 'Bestiaire 2.0 › ligne 7073');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/corbeau-agressif#carte:corbeau-agressif-noir', 3, NULL, NULL, 'Rage', 'Active un pouvoir de rage qui augmente de +3 les dégâts et de +2 les dégâts subis pendant 3 tours.', 'monstres', 'Bestiaire 2.0 › ligne 7073');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/corbeau-agressif#carte:corbeau-agressif-noir', 4, NULL, NULL, 'Mon précieux !', 'Une fois par combat, cette créature a la possibilité de voler un accessoire, un objet à la ceinture ou de l’or dans la bourse d’une cible qui possède moins de 20% de sa santé max. La victime peut tenter un jet de Stabilité ou Réflexe, si elle rate : L’objet est perdu et la créature s''enfuit.', 'monstres', 'Bestiaire 2.0 › ligne 7073');
