INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/corbeau-agressif#carte:corbeau-agressif-du-feu', 11, 'tactique', 'TACTIQUE COMBAT', 'Le chef d’une nuée de corbeau agressif, il est bien plus massif que les autres et possède une plumage qui mélange le rouge et le noir dans une harmonie troublante, presque comme si il avait des symbole lié au feu sur lui. Il est adapté pour le combat et possède assez de force pour voler une arme à une main au lieu des petits objets, il va la balancer plus loin pour que les autres corbeaux le récupèrent pendant qu’il continue le combat.', 'Bestiaire 2.0 › ligne 7208', 'monstres');
INSERT INTO monstre_caracteristique (monstre_id, caracteristique_id, rang, valeur, origine, source_ref) VALUES ('monstres/corbeau-agressif#carte:corbeau-agressif-du-feu', 'force', 1, 2, 'monstres', 'Bestiaire 2.0 › ligne 7170');
