INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/crieur-osseux#carte:gueulard-osseux', 10, 'capacites', 'Capacité(s)', 'Non-Mort. Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/crieur-osseux#carte:gueulard-osseux', 11, 'tactique', 'TACTIQUE COMBAT', 'Les gueulards ont une voix si puissante qu’elle force les ennemis à reculer. Ils sont reconnaissable car leur cage thoracique possède bien plus de cotes, est plus grosse et leur colonne vertébrale semble plus épaisse.', 'Bestiaire 2.0 › ligne 7400', 'monstres');
