INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/crieur-osseux#carte:gueulard-osseux', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 7379');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/crieur-osseux#carte:gueulard-osseux', 2, NULL, NULL, 'Squelettique', 'Rend cette créature immunisé aux attaques d’estoc', 'monstres', 'Bestiaire 2.0 › ligne 7379');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/crieur-osseux#carte:gueulard-osseux', 3, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 7379');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/crieur-osseux#carte:gueulard-osseux', 4, NULL, NULL, 'Terrain favorable', 'Si jamais la météo est "Vent violent" ou "Tempête de sable", ses dégâts augmentent de +8 et son arme a le double de sa portée.', 'monstres', 'Bestiaire 2.0 › ligne 7379');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/crieur-osseux#carte:gueulard-osseux', 5, NULL, NULL, 'Lanceur de sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Lame d''air, Propulsion, Éternuement.', 'monstres', 'Bestiaire 2.0 › ligne 7379');
