INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/cuirasse-abimee#carte:cuirasse-abime', 9, 'immunite', 'Immunité(s) Dégâts/Effets = 0', 'Poison, Maladie, Saignement, Peur, Fatigue', 'Bestiaire 2.0 › ligne 7717', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/cuirasse-abimee#carte:cuirasse-abime', 10, 'capacites', 'Capacité(s)', 'Mourir peut attendre. Cette créature n’a que la moitié de sa santé qu’elle est censée avoir. Quand elle tombe en dessous de 0 santé, elle sombre dans une mort temporaire qui ne dure qu’un tour, à la fin de ce dernier, elle revient avec toute sa santé et barrière. La deuxième mort est fatale par contre.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/cuirasse-abimee#carte:cuirasse-abime', 11, 'tactique', 'TACTIQUE COMBAT', 'Il est la défense du Cortège du Passé, il est là pour se coller aux ennemis et les empêcher de faire trop de mal aux autres morceaux d’armures. Il est assez difficile de le faire tomber à cause de ses défenses plus que bonnes.', 'Bestiaire 2.0 › ligne 7731', 'monstres');
