INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 12, 'capacites', 'Capacité(s)', 'Inerte. Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 13, 'tactique', 'TACTIQUE COMBAT', 'Un feu se propage en plein de petites poches tout aussi destructeur, il faut redoubler de prudence quand la créature commence à se diviser.', 'Bestiaire 2.0 › ligne 9271', 'monstres');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 9253');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 9253');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 3, NULL, NULL, 'Brasier unifié', 'Quand la créature perd 25% de santé, elle va se diviser en deux, ces deux nouveaux être se partagent la santé courante mais conserve la puissance de base. Ce processus peut se faire 3 fois maximum. Une fois que la première division à eu lieu, les créatures nouvelles n''ont qu’une seule initiative.', 'monstres', 'Bestiaire 2.0 › ligne 9253');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 4, '[EP3]', 3, 'Être du Feu', 'Cette créature peut utiliser tous les sorts de la magie du feu de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 9253');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 5, '[EP5]', 5, 'Petit et rapide', 'La division 2 et 3 ont un bonus de +4 à l’initiative et +1 à la vitesse.', 'monstres', 'Bestiaire 2.0 › ligne 9253');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-feu#carte:elementaire-du-feu', 6, '[EP7]', 7, 'Corps de feu', 'Chaque attaque physique/magique au contact qu''un assaillant prodigue lui oblige de faire un de vigueur pour ne pas subir "Brûlure 1".', 'monstres', 'Bestiaire 2.0 › ligne 9253');
