INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 11, 'immunite', 'Immunité(s) Dégâts/Effets = 0', 'Vent, Surdité', 'Bestiaire 2.0 › ligne 9533', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 12, 'capacites', 'Capacité(s)', 'Inerte. Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 13, 'tactique', 'TACTIQUE COMBAT', 'Cet élémentaire force ses ennemis à jouer sur son terrain, le cyclone autour de lui ne fait certes pas de dégâts mais il balaye le terrain en retirant tout les obstacles et en laissant ses ennemis galérer a approcher. Pendant qu’ils approchent lentement, l’élémentaire est libre d’attaque avec ses nombreux sorts de vent.
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 3, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 4, NULL, NULL, 'Corps de cyclone', 'Cette créature se place au centre (5x5) de la battlemap et force ses ennemis à aller dans les coins. Les ennemis doivent se déplacer dans le cyclone au centre pour lui faire des dégâts. Il est nécessaire de réussir des jet de stabilité/réflexe pour pouvoir avancer dans la tornade, un échec divise par 2 la vitesse pour 1 tour. Il est impossible de sprinter dans la tornade. Si jamais un ennemi retombe dans la tornade, il est repoussé de 1d4 cases en arrière. Au sein du cyclone, les projectiles et attaques magiques ne fonctionnent pas et ne peuvent pas atteindre le centre.', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 5, NULL, NULL, 'Allonge inattendue', 'Augmente la portée des sorts d''attaque de +3.', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 6, '[EP3]', 3, 'Être du Vent', 'Cette créature peut utiliser tous les sorts de la magie du vent de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 7, '[EP5]', 5, 'Prédateur aérien', 'Bonus de +6 dégâts contre les ennemis qui souffrent d''un malus à la vitesse ou à l''initiative (hors agilité à 1).', 'monstres', 'Bestiaire 2.0 › ligne 9537');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vent#carte:elementaire-du-vent', 8, '[EP7]', 7, 'Début transparent', 'Au début du tour, la première attaque contre lui se fera avec un désavantage.', 'monstres', 'Bestiaire 2.0 › ligne 9537');
