INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 1, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 9671');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 9671');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 3, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 9671');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 4, NULL, NULL, 'Aléa négatif', 'Chaque début de son tour, cette créature va prendre pour cible un ennemi au hasard, lance un D20 et inflige un effet négatif selon le résultat :
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 5, '[EP3]', 3, 'Être du vide', 'Cette créature peut utiliser tous les sorts de la magie du vide de son niveau.', 'monstres', 'Bestiaire 2.0 › ligne 9671');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 6, '[EP5]', 5, 'Totem du néant', 'Les ennemis à 3 cases autour de la créature ont un malus de 10% à tous les jets qui implique la volonté.', 'monstres', 'Bestiaire 2.0 › ligne 9671');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 7, '[EP7]', 7, 'Attaque dissipante', 'Tous les 2 tours, l’attaque de cette créature inflige l’effet du sort “dissipation” de la magie du vide.', 'monstres', 'Bestiaire 2.0 › ligne 9671');
INSERT INTO monstre_defense (monstre_id, sens, rang, cible, cible_cle, origine, source_ref) VALUES ('monstres/elementaire-du-vide#carte:elementaire-du-vide', 'vulnerabilite', 1, 'Espace/Temps', 'espace-temps', 'monstres', 'Bestiaire 2.0 › ligne 9663');
