INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/embrase', 'Embrasé', 'embrase', 45, 'E', 'EP4', 4, 4, 'Ce sont des condamnés à mort par le Temple du Feu pour des fautes graves envers le Temple, Séraphin ou même en dehors, ils sont purifiés dans la chambre des cendres par un feu particulier dont seul le Haut Prêtre du Feu à le secret. Toute la chair est brûlé, ne reste qu''une partie du squelette et les cendres, par une formule étrange, le squelette se relève, les parties manquante sont caché par les cendres et ils sont jetés dans le désert Doré près du Volcan, condamné à errer le temps qu''ils doivent purger. Là où il y a un embrasé, il y a eu le passage de prêtres du feu.', 'Volcan, Désert, Terres brûlées, Ruines brûlées', NULL, 'monstres', 'Bestiaire 2.0 › lignes 9754-9937');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/embrase', 1, 'Volcan', 'volcan', 'monstres', 'Bestiaire 2.0 › lignes 9754-9937');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/embrase', 2, 'Désert', 'desert', 'monstres', 'Bestiaire 2.0 › lignes 9754-9937');
