INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/embrase#carte:embrase', 4, NULL, NULL, 'Élément Feu', 'L’élément d’attaque de cette créature est le Feu avec 25% de chance d’obliger un jet de vigueur à la cible, si elle rate, elle prend “Brûlure 1”.', 'monstres', 'Bestiaire 2.0 › ligne 9799');
