INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/fulgurame#carte:fulgurame-foudroyant', 9, 'immunite', 'Immunité(s) Dégâts/Effets = 0', 'Poison, Maladie, Couardise, Peur, Fatigue, Aveuglement, Saignement, Estoc, Paralysie Paralysie', 'Bestiaire 2.0 › ligne 10382', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/fulgurame#carte:fulgurame-foudroyant', 10, 'capacites', 'Capacité(s)', 'Non-Mort. Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/fulgurame#carte:fulgurame-foudroyant', 11, 'tactique', 'TACTIQUE COMBAT', 'Le foudroyant possède de la foudre qui circule en dehors de son corps en permanence, ce qui fait qu’il fait planer une menace constante pour ceux qui oseraient l''attaquer avec des armes de contact, il les force un jet de vigueur pour ne pas qu’il souffre de paralysie. Au-delà de ça, son armure de cellulose fer est bien meilleure, renforcée par sa foudre.', 'Bestiaire 2.0 › ligne 10404', 'monstres');
