INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/fulgurame#carte:fulgurame-foudroyant', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 10386');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/fulgurame#carte:fulgurame-foudroyant', 2, NULL, NULL, 'Squelettique', 'Rend cette créature immunisé aux attaques d’estoc', 'monstres', 'Bestiaire 2.0 › ligne 10386');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/fulgurame#carte:fulgurame-foudroyant', 3, NULL, NULL, 'Initiative extrême', 'Permet d''avoir un bonus de +10 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 10386');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/fulgurame#carte:fulgurame-foudroyant', 4, NULL, NULL, 'Lame foudroyante', '(IC) En échange de 5 chakra, la prochaine attaque physique au contact libère une foudre qui inflige 1d8 dégâts qui va ignorer l’AM et l’AP de la cible.', 'monstres', 'Bestiaire 2.0 › ligne 10386');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/fulgurame#carte:fulgurame-foudroyant', 5, NULL, NULL, 'Réfléxe éclair', '(IC) En échange de 5 chakra, augmente son prochain jet de défense de 10%.', 'monstres', 'Bestiaire 2.0 › ligne 10386');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/fulgurame#carte:fulgurame-foudroyant', 6, NULL, NULL, 'Corps électrique', 'Chaque attaque au contact qu''un assaillant prodigue lui oblige de faire un de vigueur pour ne pas subir "Paralysie 1".', 'monstres', 'Bestiaire 2.0 › ligne 10386');
