INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/gardien-du-passe#carte:gardien-du-passe', 11, 'tactique', 'TACTIQUE COMBAT', 'Le Gardien du Passé est un puissant adversaire à affronter, il possède une versatilité qui fait en grande partie sa puissance. Il est capable d’utiliser des armes de contact, à distance, utiliser un large panel de sorts, possède beaucoup de défenses, bref … une véritable épreuve. Sa défense en plus n’est pas fixe de partout, sa plus grosse protection est au corps et les parties les moins protégées impliquent de viser. Bonne chance !', 'Bestiaire 2.0 › ligne 10623', 'monstres');
