INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/gobelin-mage', 'Gobelin Mage', 'gobelin-mage', 54, 'G', 'EP1', 1, 1, 'Les Gobelins Mage sont de loin les plus intelligents de leur espèce. On les retrouvent souvent en tant que conseillés des Hobgobelins ou bien à préparer divers poisons et surtout du brai noir pour les archers. Leur cervelle moins atrophiée que leurs confrères et consœurs compense leur inaptitude au combat au corps-à-corps. Même si ils savent un minimum manier un bâton.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 11147-11315');
