INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-darcane#carte:golem-darcane-iii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 11459');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-darcane#carte:golem-darcane-iii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 11459');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-darcane#carte:golem-darcane-iii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 11459');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-darcane#carte:golem-darcane-iii', 4, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 11459');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-darcane#carte:golem-darcane-iii', 5, NULL, NULL, 'Immatériel', 'Cette créature est naturellement immunisée aux dégâts physiques (armes) , seules la magie, une arme spectrale ou une arme sous l’effet d’un sort “fer” peuvent la toucher.', 'monstres', 'Bestiaire 2.0 › ligne 11459');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-darcane#carte:golem-darcane-iii', 6, NULL, NULL, 'Rune immédiate', 'Cette créature obtient une résistance à l’élément du dernier sort subi et cela plusieurs fois dans un tour (une résistance à la fois).', 'monstres', 'Bestiaire 2.0 › ligne 11459');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-darcane#carte:golem-darcane-iii', 7, NULL, NULL, 'Coup alternatif', 'Permet de choisir si l''attaque va prendre en compte l''armure physique ou bien l''armure magique de la cible.', 'monstres', 'Bestiaire 2.0 › ligne 11459');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-darcane#carte:golem-darcane-iii', 8, NULL, NULL, 'Miroir partiel', 'Renvoi à hauteur de 25% des effets du sort de l’adversaire (l’agresseur peut se défendre contre cette contre attaque si c’est possible)', 'monstres', 'Bestiaire 2.0 › ligne 11459');
