INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/golem-de-bois#carte:golem-de-bois-iii', 11, 'tactique', 'TACTIQUE COMBAT', 'Cette version plus évoluée du golem de bois possède un bras tubulaire avec lequel il est capable de tirer moult projectile, allant du rocher au fruit, même à distance, personne n’est à l’abri.', 'Bestiaire 2.0 › ligne 11986', 'monstres');
