INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-bois#carte:golem-de-bois-iii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 11966');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-bois#carte:golem-de-bois-iii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 11966');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-bois#carte:golem-de-bois-iii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 11966');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-bois#carte:golem-de-bois-iii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 11966');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-bois#carte:golem-de-bois-iii', 5, NULL, NULL, 'Racine', 'Tant qu''il est sur de la terre, cette créature récupère 3 santé au début de son tour.', 'monstres', 'Bestiaire 2.0 › ligne 11966');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-bois#carte:golem-de-bois-iii', 6, NULL, NULL, 'Éclatement en bois', 'Action utilisable tous les 5 tours, cette créature peut projeter des éclats de bois acérés dans un rayon de 4 cases autour de lui. Toutes les créatures situées dans la zone subissent 6d6 dégâts de taille.', 'monstres', 'Bestiaire 2.0 › ligne 11966');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-bois#carte:golem-de-bois-iii', 7, NULL, NULL, 'Mortier', 'Cette créature possède une arme qui peut tirer des projectiles et est considérée comme une arbalète dans la stats qu’il faut utiliser. Les projectiles tirés par cette arme ignore 3AP mais sont détruits après utilisation.', 'monstres', 'Bestiaire 2.0 › ligne 11966');
