INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/golem-de-boue', 'Golem de boue', 'golem-de-boue', 58, 'G', 'EP2', 2, 2, 'Le golem de boue est une créature imposante, formée d’un mélange mouvant de terre détrempée et d’argile sombre. Son corps large et bosselé paraît sculpté dans un marais vivant, parcouru de fissures d’où s’échappe un limon gluant. Sa tête informe n’a souvent qu’une simple fente luisante en guise de regard, comme un œil unique suintant de vase. De ses bras massifs émergent de longues griffes tranchantes. Le golem de boue est le gardien silencieux des marécages et des rivières polluées, surgissant des eaux troubles pour défendre son territoire.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-de-boue', 1, 'Marais', 'marais', 'monstres', 'Bestiaire 2.0 › lignes 12075-12343');
