INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-chair#carte:golem-de-chair-ii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 12461');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-chair#carte:golem-de-chair-ii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 12461');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-chair#carte:golem-de-chair-ii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 12461');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-chair#carte:golem-de-chair-ii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 12461');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-chair#carte:golem-de-chair-ii', 5, NULL, NULL, 'Forme changeante', 'Cette créature à tout les début de tour (juste après l''initiative et avant tout le monde) change aléatoirement de forme et ainsi les bonus qu''elle possède, il y a 8 formes :
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-chair#carte:golem-de-chair-ii', 6, NULL, NULL, 'Attaque multiple', 'Cette créature peut taper sur 3 axes quand il attaque avec ses armes (Devant, Gauche, Droite) [NOTE : 4 axes quand il est sous la forme 5 lui ajoute derrière lui]', 'monstres', 'Bestiaire 2.0 › ligne 12461');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-chair#carte:golem-de-chair-ii', 7, NULL, NULL, 'Baroud', 'Si la santé tombe à 0, possède un dernier tour d’action, si sa santé remonte en positif pendant ce dernier tour, le don est de nouveau actif.', 'monstres', 'Bestiaire 2.0 › ligne 12461');
