INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-corail#carte:golem-de-corail-ii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 12753');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-corail#carte:golem-de-corail-ii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 12753');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-corail#carte:golem-de-corail-ii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 12753');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-corail#carte:golem-de-corail-ii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 12753');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-corail#carte:golem-de-corail-ii', 5, NULL, NULL, 'Squelettique', 'Rend cette créature immunisée aux attaques d’estoc.', 'monstres', 'Bestiaire 2.0 › ligne 12753');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-corail#carte:golem-de-corail-ii', 6, NULL, NULL, 'Souffle élémentaire', 'Cette créature est capable de cracher un souffle lié à son élément. Ce souffle est capable d''infliger l''altération d''état lié à l''élément à hauteur de 35% de chance de l''infliger. (les joueurs doivent faire les jets en conséquences pour ne pas prendre l''altération d''état)', 'monstres', 'Bestiaire 2.0 › ligne 12753');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-corail#carte:golem-de-corail-ii', 7, NULL, NULL, 'Réparation', 'Cette créature récupère 2d6 barrière au début de son tour.', 'monstres', 'Bestiaire 2.0 › ligne 12753');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-corail#carte:golem-de-corail-ii', 8, NULL, NULL, 'Humidification', 'Dispose d''une protection qui vont ignorer les 10 premiers dégâts qui vont lui être infligés lors d''un combat (se recharge tous les 3 tours)', 'monstres', 'Bestiaire 2.0 › ligne 12753');
