INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/golem-de-corail-2', 'Golem de corail', 'golem-de-corail', 61, 'G', 'EP5', 5, 5, 'Le golem de corail est une entité unique née des profondeurs marines, une conscience collective de coraux qui a fusionné pour donner naissance à une forme humanoïde. Son corps est un entrelacs de branches calcaires et d’éponges colorées, rappelant un squelette vivant aussi fragile qu’implacable. Contrairement à d’autres golems, il est impossible d’en fabriquer artificiellement, seuls les récifs anciens et mystérieux peuvent en engendrer un. Bien qu’il bouge lentement, il reste puissant une fois qu’il arrive devant sa cible. Sa particularité la plus inquiétante est sa capacité à parasiter les corps noyés ou morts qu’il rencontre, les recouvrant de coraux jusqu’à les transformer en Squelrail, des squelettes entièrement colonisés par le corail, obéissant à sa volonté. Gardien des fonds marins, il veille sur les récifs et punit ceux qui cherchent à piller la mer, incarnant à la fois la beauté et la cruauté de l’océan.', 'Mer, Plage, Rivière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 12934-13205');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-de-corail-2', 1, 'Mer', 'mer', 'monstres', 'Bestiaire 2.0 › lignes 12934-13205');
