INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 11, 'tactique', 'TACTIQUE COMBAT', 'En plus de faire de gros dégâts, cette version du golem de cristal est capable d’annuler les bonus d’un adversaire et va même se concentrer sur les adversaires qui auront tendance à se préparer avant une attaque.', 'Bestiaire 2.0 › ligne 13404', 'monstres');
