INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 13377');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 13377');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 13377');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 13377');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 5, NULL, NULL, 'Attaque immatérielle', 'Les armes de cette créature ignorent les AP données par les armures.', 'monstres', 'Bestiaire 2.0 › ligne 13377');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 6, NULL, NULL, 'Invisible', 'Cette créature est invisible à l''œil nu, il faudra être inventif pour la repérer (météo, farine, terre, sable, etc …)', 'monstres', 'Bestiaire 2.0 › ligne 13377');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 7, NULL, NULL, 'Sournois', 'Quand l’adversaire n’est pas attentif à l’attaquant, permet d’infliger un bonus de 2d4 dégâts en plus des dégâts de l’arme.', 'monstres', 'Bestiaire 2.0 › ligne 13377');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 8, NULL, NULL, 'Implosion', 'Quand cette créature perd 25% de sa santé, elle explose et pose une zone de pression automatiquement sur une zone de 5x5 qui empêche les créature dans cette dernière de bouger pour leur prochain tour.', 'monstres', 'Bestiaire 2.0 › ligne 13377');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 9, NULL, NULL, 'Attaque dissipante', 'Tous les 2 tours, l’attaque de cette créature inflige l’effet du sort “dissipation” de la magie du vide.', 'monstres', 'Bestiaire 2.0 › ligne 13377');
INSERT INTO monstre_defense (monstre_id, sens, rang, cible, cible_cle, origine, source_ref) VALUES ('monstres/golem-de-cristal#carte:golem-de-cristal-iii', 'vulnerabilite', 1, 'Temps/Espace', 'temps-espace', 'monstres', 'Bestiaire 2.0 › ligne 13367');
