INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/golem-de-glace', 'Golem de glace', 'golem-de-glace', 63, 'G', 'EP4', 4, 4, 'Le golem de glace est une imposante statue vivante, façonnée dans la plus pure des glaces, aux formes humaines parfaitement sculptées. Dépourvu de visage, il incarne l’absence d’âme et de compassion, avançant implacablement dans le blizzard éternel d’Enhor, son unique domaine. On ne le trouve que dans ces terres glacées, là où tempêtes et sommets enneigés forgent son essence. Contrairement à d’autres golems, il ne dispose d’aucune défense physique : ses membres de glace se brisent facilement. Pourtant, son corps est protégé par une défense magique colossale qui le rend difficile à gérer sur le plan magique. Chaque coup reçu se dissipe comme s’il frappait le blizzard lui-même, tandis que le golem continue d’avancer, froid et inébranlable, symbole éternel de la glace.', 'Enhor, zone de froid extérieur ou intérieur', NULL, 'monstres', 'Bestiaire 2.0 › lignes 13495-13760');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-de-glace', 1, 'Enhor', 'enhor', 'monstres', 'Bestiaire 2.0 › lignes 13495-13760');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-de-glace', 2, 'zone de froid extérieur ou intérieur', 'zone-de-froid-exterieur-ou-interieur', 'monstres', 'Bestiaire 2.0 › lignes 13495-13760');
