INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/golem-de-fer#carte:golem-de-fer-iii', 11, 'tactique', 'TACTIQUE COMBAT', 'Le torse de ce golem de fer ressemble à une grille dans lequel on peut y voir son noyau qui chauffe énormément, baignant d’une sorte d’énergie brûlante. Sa vulnérabilité au feu devient un absorption qui lui permet d’augmenter sa force et sa vitesse temporairement.', 'Bestiaire 2.0 › ligne 13935', 'monstres');
