INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/golem-de-foudre', 'Golem de foudre', 'golem-de-foudre', 65, 'G', 'EP5', 5, 5, 'Version évolué des golem de mine, les golem de foudre sont des créatures très sophistiqué qui est en grosse majorité d’origine artificielle. On peut en retrouver à l’état naturel mais ils sont assez facilement identifiable par leur apparence comme beaucoup plus brut et moins sophistiqué que les artificiels. Ils sont parfaitement adaptés au travail dans les mines et sont même idéal pour trouver des filons de métaux. Leur corps complètement fait de métal de différent type rendent son corps dur et capable d’attirer la foudre pour la redistribuer dans une autre direction.', 'Mine, Caverne', NULL, 'monstres', 'Bestiaire 2.0 › lignes 14024-14286');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-de-foudre', 1, 'Mine', 'mine', 'monstres', 'Bestiaire 2.0 › lignes 14024-14286');
