INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-foudre#carte:golem-de-foudre-iii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 14179');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-foudre#carte:golem-de-foudre-iii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 14179');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-foudre#carte:golem-de-foudre-iii', 5, NULL, NULL, 'Élément Foudre', 'L’arme de cette créature possède 30% de chance d’obliger un jet de vigueur à l’adversaire pour ne pas qu’il prenne paralysie 1”. L’arme peut taper dans l’élément associé.', 'monstres', 'Bestiaire 2.0 › ligne 14179');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-foudre#carte:golem-de-foudre-iii', 6, NULL, NULL, 'Plaque miroir', 'Possède une plaque miroir qui peut absorber un sort niveau 3 maximum, cette plaque réapparaît tous les 3 tours.', 'monstres', 'Bestiaire 2.0 › ligne 14179');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-foudre#carte:golem-de-foudre-iii', 7, NULL, NULL, 'Distributeur de foudre', 'Chaque attaque de l’élément foudre va se distribuer à la cible la plus proche de la première (maximum 3 PO) et infliger la moitié des dégâts et ainsi de suite …', 'monstres', 'Bestiaire 2.0 › ligne 14179');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-foudre#carte:golem-de-foudre-iii', 8, NULL, NULL, 'Anti Brumeux', 'Cette créature inflige un bonus de 10 dégâts contre les créature lié à la Brume Noir et peut protéger ses alliés à 4 cases de lui des effets négatifs de cette dernière.', 'monstres', 'Bestiaire 2.0 › ligne 14179');
