INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/golem-de-marbre#carte:golem-de-marbre-i', 10, 'tactique', 'TACTIQUE COMBAT', 'Gardien des lieux de culte et reflet d’êtres bons, le golem de marbre est une créature dont le corps massif n’est pas à prendre à la légère, il possède une grande force qu’il n’hésite pas une seconde à exploiter pour détruire les intrus à son environnement. Il possède des défenses plus que remarquables, il ne possède aucunes faiblesses magiques, son point faible repose à son défaut de construction qui se trouve à ses articulation aux jambes et bras, ces points faibles sont petits et impose un gros malus pour les toucher. Prudence, il sera difficile à détruire.
INSERT INTO monstre_caracteristique (monstre_id, caracteristique_id, rang, valeur, origine, source_ref) VALUES ('monstres/golem-de-marbre#carte:golem-de-marbre-i', 'force', 1, 7, 'monstres', 'Bestiaire 2.0 › ligne 14323');
