INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-marbre#carte:golem-de-marbre-i', 5, NULL, NULL, 'Rempart fragile', 'L’AP et l’AM de cette créature sont très élevés mais elle possède un point faible qui ne dispose pas de cette défense (le point faible varie selon les créatures) (Point faible = Articulation [malus 25% pour toucher])', 'monstres', 'Bestiaire 2.0 › ligne 14337');
