INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-magma#carte:golem-de-magma-iii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 14751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-magma#carte:golem-de-magma-iii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 14751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-magma#carte:golem-de-magma-iii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 14751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-magma#carte:golem-de-magma-iii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 14751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-magma#carte:golem-de-magma-iii', 5, NULL, NULL, 'Élément Feu', 'L’arme de cette créature possède 30% de chance d’obliger un jet de vigueur à l’adversaire pour ne pas qu’il prenne “brûlure 1”. L’arme peut taper dans l’élément associé.', 'monstres', 'Bestiaire 2.0 › ligne 14751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-magma#carte:golem-de-magma-iii', 6, NULL, NULL, 'Bouclier de feu', 'Projette des flammes inesquivables qui infligent 2d6 en réponse à toutes agressions au corps à corps.', 'monstres', 'Bestiaire 2.0 › ligne 14751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-magma#carte:golem-de-magma-iii', 7, NULL, NULL, 'Super explosion', 'Les projectiles de cette créature touche une zone de 3x3 au lieu de 2x2.', 'monstres', 'Bestiaire 2.0 › ligne 14751');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-magma#carte:golem-de-magma-iii', 8, NULL, NULL, 'Moteur à vapeur', 'Quand il prend une attaque de l’élément Eau ou Vent, sa vitesse augmente de +2 pendant 2 tours. Si la météo est positive pour le Vent ou l’Eau, sa vitesse de base monte à 4 et il a +3 à l’initiative.', 'monstres', 'Bestiaire 2.0 › ligne 14751');
