INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-nuage#carte:golem-de-nuage-iii', 6, NULL, NULL, 'Caprice météorologique++', 'La météo change tous les tours.', 'monstres', 'Bestiaire 2.0 › ligne 15203');
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/golem-de-lumiere', 'Golem de lumière', 'golem-de-lumiere', 70, 'G', 'EP3', 3, 3, 'Le golem de lumière est une sentinelle élancée, forgée dans un matériau qui semble rayonner de l’intérieur. Plus petit et plus agile que les autres golems, il adopte toujours une silhouette féminine, en hommage à la déesse de la lumière. Il manie un arc façonné dans une matière translucide, capable de créer des flèches de lumière pure. Ces projectiles percent ses adversaires et peuvent aveugler leurs cibles à l’impact. Souvent posté sur les hauteurs ou aux abords des sanctuaires, il veille et frappe avec précision toute menace approchant.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-de-lumiere', 1, 'Là où la lumière pointe le plus fort', 'la-ou-la-lumiere-pointe-le-plus-fort', 'monstres', 'Bestiaire 2.0 › lignes 15329-15585');
