INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/golem-dombre', 'Golem d’ombre', 'golem-dombre', 71, 'G', 'EP3', 3, 3, 'Le golem de l’ombre est une silhouette élancée et élégante, sculptée dans une matière sombre qui absorbe la lumière autour de lui. Toujours raffiné, il porte l’apparence d’un noble ou d’un assassin masqué, rappelant le style sophistiqué du dieu de l’ombre. Ses mouvements sont silencieux, presque irréels, et ses contours semblent se fondre dans les ténèbres à chaque pas. Il manie deux lames formées d’ombre pure, qui se reforment instantanément lorsqu’elles sont brisées ou dissipées.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-dombre', 1, 'Là où l’ombre domine', 'la-ou-lombre-domine', 'monstres', 'Bestiaire 2.0 › lignes 15593-15848');
