INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-i', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 16569');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-i', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 16569');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-i', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 16569');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-i', 4, NULL, NULL, 'Gluant', 'Cette créature est faite dans une matière gélatineuse, ce qui lui permet d’être résistante face au dégâts de frappe. Sa structure lui inflige une faiblesse contre la paralysie.', 'monstres', 'Bestiaire 2.0 › ligne 16569');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-i', 5, NULL, NULL, 'Pétronage', 'La vitesse de nage dans le pétrole ou les marais est doublée, la vitesse augmente de +2 sous la météo “Pluie pétrole”. Peut nager dans de l’eau non magique.', 'monstres', 'Bestiaire 2.0 › ligne 16569');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-i', 6, NULL, NULL, 'Poison noir', 'Chaque attaque de cette créature infligent de la corruption à hauteur de 10% des dégâts infligés (minimum 1 corruption infligé)', 'monstres', 'Bestiaire 2.0 › ligne 16569');
