INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-i', 8, '[Enflammé]', NULL, 'Élément Feu', 'L’arme de cette créature possède 30% de chance d’obliger un jet de vigueur à l’adversaire pour ne pas qu’il prenne “brûlure 1”. L’arme peut taper dans l’élément associé.', 'monstres', 'Bestiaire 2.0 › ligne 16569');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-i', 9, '[Enflammé]', NULL, 'Bouclier de feu', 'Projette des flammes inesquivables qui infligent 2d6 en réponse à toutes agressions au corps à corps.', 'monstres', 'Bestiaire 2.0 › ligne 16569');
