INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 12, 'tactique', 'TACTIQUE COMBAT', 'Cette version géante du monstre des marais a engendré tellement de matière qu’il est capable en cas de danger d’en libérer une partie pour polluer l’environnement autour de lui ainsi que ses ennemis.', 'Bestiaire 2.0 › ligne 16768', 'monstres');
