INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 16729');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 16729');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 16729');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 16729');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 5, NULL, NULL, 'Gluant', 'Cette créature est faite dans une matière gélatineuse, ce qui lui permet d’être résistante face au dégâts de frappe. Sa structure lui inflige une faiblesse contre la paralysie.', 'monstres', 'Bestiaire 2.0 › ligne 16729');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 6, NULL, NULL, 'Pétronage', 'La vitesse de nage dans le pétrole ou les marais est doublée, la vitesse augmente de +2 sous la météo “Pluie pétrole”. Peut nager dans de l’eau non magique.', 'monstres', 'Bestiaire 2.0 › ligne 16729');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 7, NULL, NULL, 'Poison noir', 'Chaque attaque de cette créature infligent de la corruption à hauteur de 10% des dégâts infligés (minimum 1 corruption infligé)', 'monstres', 'Bestiaire 2.0 › ligne 16729');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 8, '[Non enflammé]', NULL, 'Pollution', 'Chaque attaque qui touche oblige un jet de vigueur qui donne ces effets pendant 2 tours :
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 9, '[Non enflammé]', NULL, 'Explosion noire', 'Si cette créature perd 25% de sa santé max alors qu’il n’est pas enflammé, il libère de la matière partout autour de lui, obligeant un jet de parade/esquive avec un malus de 20% à tous ceux présent sur le terrain. Inflige 2d6 de corruption et 30 dégâts neutre (réduisible par l’AM).', 'monstres', 'Bestiaire 2.0 › ligne 16729');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-petrole#carte:golem-de-petrole-iii', 10, '[Enflammé]', NULL, 'Élément Feu', 'L’arme de cette créature possède 30% de chance d’obliger un jet de vigueur à l’adversaire pour ne pas qu’il prenne “brûlure 1”. L’arme peut taper dans l’élément associé.', 'monstres', 'Bestiaire 2.0 › ligne 16729');
