INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/golem-de-rouage', 'Golem de rouage', 'golem-de-rouage', 75, 'G', 'EP9', 9, 9, 'Le golem de Rouage est un gardien mécanique énigmatique, dont le corps est constitué d’innombrables engrenages de cuivre qui tournent sans jamais s’arrêter. Des lueurs rosées brillent dans ses zones sensibles, comme son cœur et sa tête, rappelant une énergie d’origine divine. Selon les légendes, ces colosses auraient été bénis par les dieux du Temps et de l’Espace afin de protéger les mystères les plus dangereux de ces magies. Leur mission sacrée est de traquer et punir ceux qui osent manipuler l’espace-temps de façon abusive. Bien que rares, on les aperçoit parfois au détour d’une faille dimensionnelle, surgissant comme des ombres mécaniques hors de la réalité. Comme tous les golems, ils ne font preuve d’aucune hésitation : toute intrusion dans leur domaine est perçue comme une menace, et ils attaquent avec une précision implacable.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-de-rouage', 1, 'Faille temporelle', 'faille-temporelle', 'monstres', 'Bestiaire 2.0 › lignes 16857-17137');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-de-rouage', 2, 'Couloir du temps', 'couloir-du-temps', 'monstres', 'Bestiaire 2.0 › lignes 16857-17137');
