INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-sel#carte:golem-de-sel-i', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 17467');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-sel#carte:golem-de-sel-i', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 17467');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-sel#carte:golem-de-sel-i', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 17467');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-sel#carte:golem-de-sel-i', 4, NULL, NULL, 'Élément Terre', 'L’arme de cette créature possède 30% de chance d’obliger un jet de fermeté à l’adversaire pour ne pas qu’il prenne “pétrifié 1”. L’arme peut taper dans l’élément associé et ses sorts de terre infligent également un bonus de +3 aux dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 17467');
