INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-sel#carte:golem-de-sel-iii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 17592');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-sel#carte:golem-de-sel-iii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 17592');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-sel#carte:golem-de-sel-iii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 17592');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-sel#carte:golem-de-sel-iii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 17592');
