INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/golem-de-verre', 'Golem de verre', 'golem-de-verre', 78, 'G', 'EP5', 5, 5, 'Les Golems de Verre sont des créatures que l''on retrouve principalement dans les déserts et verreries. Les rares spécimens trouvés à l''état naturel sont d''anciens golems de sable ayant subi une forte pression suite à une explosion de grande ampleur. Ce qui rend leur origine souvent difficile à expliquer, même si certains ont été créés accidentellement suite à des combats impliquant un puissant utilisateur du Feu. Pour ce qui est des spécimens artificiels, ils sont tout simplement créés par des maître-verriers, avec autant de raffinement et de précision que les sculpteurs de golems de marbre.', 'Désert, Verreries', NULL, 'monstres', 'Bestiaire 2.0 › lignes 17705-18004');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-de-verre', 1, 'Désert', 'desert', 'monstres', 'Bestiaire 2.0 › lignes 17705-18004');
