INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-iii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 17893');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-iii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 17893');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-iii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 17893');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-iii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 17893');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-iii', 5, NULL, NULL, 'Fait de verre', 'Cette créature possède énormément de résistances magiques mais possède une forte vulnérabilité contre les dégâts sonores.', 'monstres', 'Bestiaire 2.0 › ligne 17893');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-iii', 6, NULL, NULL, 'Verre pilé', 'A chaque coup physique encaissé, des éclats de verre sont envoyés à l’attaquant, infligeant 3d6 dégâts neutre.', 'monstres', 'Bestiaire 2.0 › ligne 17893');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-iii', 7, NULL, NULL, 'Réflexion du verre', 'Cette créature de renvoyer les dégâts/effets magiques ou physiques de l’élément lumière, en plus de ne prendre aucun dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 17893');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-iii', 8, NULL, NULL, 'Réfraction du verre', 'Non content de renvoyer les sorts de lumière, cette créature peut renvoyer le sort dans la direction qu’il souhaite.', 'monstres', 'Bestiaire 2.0 › ligne 17893');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-verre#carte:golem-de-verre-iii', 9, NULL, NULL, 'Défense prismatique', 'Quand un coup à été encaissé d’un certain élément, sa résistance à ce dernier augmente pendant 1 tour (cumulable).', 'monstres', 'Bestiaire 2.0 › ligne 17893');
