INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 12, 'capacites', 'Capacité(s)', 'Golem. Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 13, 'tactique', 'TACTIQUE COMBAT', 'Le cœur de ce golem de vitrail réagit aux coups qu’on lui porte et semble cumuler l’énergie des attaques pour concentrer le tout en une grosse onde qui va toucher tout le monde sur le terrain. Prudence, ne soyez pas tenté de lui faire trop de dégâts d’un coup, il pourrait vous le rendre.', 'Bestiaire 2.0 › ligne 18267', 'monstres');
INSERT INTO monstre_caracteristique (monstre_id, caracteristique_id, rang, valeur, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 'force', 1, 4, 'monstres', 'Bestiaire 2.0 › ligne 18204');
