INSERT INTO monstre_attaque (monstre_id, rang, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 1, 'Aiguille de Vitrail', '4d10 + 20 dégâts de taille/estoc', 'monstres', 'Bestiaire 2.0 › ligne 18194');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 5, NULL, NULL, 'Fait de verre', 'Cette créature possède énormément de résistances magiques mais possède une forte vulnérabilité contre les dégâts sonores.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 6, NULL, NULL, 'Attaque sanglante', 'Les armes naturelles de cette créature obligent le jet de vigueur pour ne pas prendre “Saignement 1”.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 7, NULL, NULL, 'Rempart fragile', 'L’AP et l’AM de cette créature sont très élevés mais elle possède un point faible qui ne dispose pas de cette défense (le point faible varie selon les créatures) (Point faible = Coeur)', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 8, NULL, NULL, 'Anti-loi', 'Cette créature inflige +5 dégâts contre les créatures loyales.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 9, NULL, NULL, 'Anti-bien', 'Cette créature inflige +5 dégâts contre les créatures bonnes.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 10, NULL, NULL, 'Verre pilé', 'A chaque coup physique encaissé, des éclats de verre sont envoyés à l’attaquant, infligeant 3d10 dégâts neutre.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 11, NULL, NULL, 'Réflexion du vitrail', 'Cette créature de renvoyer les dégâts/effets magiques ou physiques de l’élément lumière et ombre, en plus de ne prendre aucun dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 12, NULL, NULL, 'Réfraction du vitrail', 'Non content de renvoyer les sorts de lumière et d’ombre, cette créature peut renvoyer le sort dans la direction qu’il souhaite.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-de-vitrail#carte:golem-de-vitrail-iii', 13, NULL, NULL, 'Coeur prismatique', 'Cumule les dégâts encaissés pendant le tour où le cœur est exposé, inflige un coup qui touchera tout le monde sur le terrain avec un malus de 30% pour le jet de défense (dégâts du coup = dégâts cumulés ÷ 10). Ce coup ignore 50% des AP et AM.', 'monstres', 'Bestiaire 2.0 › ligne 18228');
