INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/golem-osseux', 'Golem osseux', 'golem-osseux', 80, 'G', 'EP6', 6, 6, 'Le golem osseux est un amalgame de squelettes, portant avec eux toute la noirceur de leurs âmes dérangées de leur repos éternel. Les corps sont broyés pour constituer le corps de ce géant poussiéreux et sinistre, imitant l''anatomie d''un ogre ainsi que leur cruauté envers leurs collègues qu''ils fustigent de leur fouet squelettique. Même si ce golem est normalement, uniquement artificiel, certains affirment que lors de certaines nuits, les cimetières et ossuaires abandonnés ainsi que champs de batailles oubliés se réveillent à l''occasion. C''est alors que ces gardiens surgissent et poussent un cri de douleur terrifiant, comme pour faire comprendre aux vivants que les morts les observent toujours.', 'Ruines, Champ de bataille, Cimetière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 18360-18642');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-osseux', 1, 'Ruines', 'ruines', 'monstres', 'Bestiaire 2.0 › lignes 18360-18642');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-osseux', 2, 'Champ de bataille', 'champ-de-bataille', 'monstres', 'Bestiaire 2.0 › lignes 18360-18642');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/golem-osseux', 3, 'Cimetière', 'cimetiere', 'monstres', 'Bestiaire 2.0 › lignes 18360-18642');
