INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 1, NULL, NULL, 'Golem', 'Cette créature ne peut récupérer de la santé que via des réparations ou des sorts adaptés.', 'monstres', 'Bestiaire 2.0 › ligne 18526');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 2, NULL, NULL, 'Inerte', 'Cette créature possède 10 de volonté et est donc immunisée contre les jets de Volonté (sauf les altérations d’état dont il est vulnérable, là il n’a que 50% de chance de les éviter).', 'monstres', 'Bestiaire 2.0 › ligne 18526');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 3, NULL, NULL, 'Inaltérable', 'Résiste aux sorts ou actions qui pourrait lui détruire sa structure.', 'monstres', 'Bestiaire 2.0 › ligne 18526');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité/réflexe pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 18526');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 5, NULL, NULL, 'Squelettique', 'Rend cette créature immunisée aux attaques d’estoc.', 'monstres', 'Bestiaire 2.0 › ligne 18526');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 6, NULL, NULL, 'Aura de frayeur', 'Sur un zone de 3 autour de lanceur, force le jet de fermeté aux adversaires pour ne pas prendre “peur 1”.', 'monstres', 'Bestiaire 2.0 › ligne 18526');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 7, NULL, NULL, 'Aura des brisés', 'Sur un zone de 3 autour de lanceur, impose un malus de 10% aux jets d’esquive/parade/psychologie des adversaires.', 'monstres', 'Bestiaire 2.0 › ligne 18526');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 8, NULL, NULL, 'Aura des affaiblis', 'Sur un zone de 3 autour de lanceur, impose un malus de 10% aux jets d’arme lourde/arme légère/arbalète/arc/magie/concentration des adversaires.', 'monstres', 'Bestiaire 2.0 › ligne 18526');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 9, NULL, NULL, 'Appels aux morts', 'Si cette créature tombe en dessous de 20% de santé, elle invoque automatiquement deux squelettes (cf. Squelette ennemi simple).', 'monstres', 'Bestiaire 2.0 › ligne 18526');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 10, NULL, NULL, 'Aura de grand chef', 'Donne un bonus de +5 aux dégâts de ses alliés tant qu’il est encore debout.', 'monstres', 'Bestiaire 2.0 › ligne 18526');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/golem-osseux#carte:golem-osseux-iii', 11, NULL, NULL, 'Super aura', 'Les passifs en zone ont une portée augmentée de 2.', 'monstres', 'Bestiaire 2.0 › ligne 18526');
