INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/hallebarde-amochee#carte:cuirasse-abime', 9, 'immunite', 'Immunité(s) Dégâts/Effets = 0', 'Poison, Maladie, Saignement, Peur, Fatigue', 'Bestiaire 2.0 › ligne 18893', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/hallebarde-amochee#carte:cuirasse-abime', 10, 'capacites', 'Capacité(s)', 'Mourir peut attendre. Cette créature n’a que la moitié de sa santé qu’elle est censée avoir. Quand elle tombe en dessous de 0 santé, elle sombre dans une mort temporaire qui ne dure qu’un tour, à la fin de ce dernier, elle revient avec toute sa santé et barrière. La deuxième mort est fatale par contre.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/hallebarde-amochee#carte:cuirasse-abime', 11, 'tactique', 'TACTIQUE COMBAT', 'Il est le second attaquant du Cortège, plus prudent que l’Épée Rouillée, il essayera toujours de profiter au maximum de la portée de son arme et d’affaiblir le maximum de cible, il aura tendance à soutenir offensivement les autres membres du Cortège. Son absence de résistance physique et magique font qu’il tombe aussi vite que son homologue de corps à corps.', 'Bestiaire 2.0 › ligne 18907', 'monstres');
INSERT INTO monstre_caracteristique (monstre_id, caracteristique_id, rang, valeur, origine, source_ref) VALUES ('monstres/hallebarde-amochee#carte:cuirasse-abime', 'force', 1, 6, 'monstres', 'Bestiaire 2.0 › ligne 18875');
