INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/herbe-folle#carte:herbe-folle-2-yeux', 10, 'tactique', 'TACTIQUE COMBAT', 'Les herbes folles sont plus maligne qu’on le penserai et elles sont capablent de stratégie quand l’adversaire en face semble costaud. Elles connaissent les bases de la magie et savent qu’elles ne doivent pas utiliser leur magie n’importe comment.', 'Bestiaire 2.0 › ligne 18975', 'monstres');
