INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/irapullum', 'Irapullum', 'irapullum', 84, 'I', 'EP3', 3, 3, 'Variante monstrueuse de l’Équipullum, cette créature est le fruit d’une corruption mêlant magie du Sang et de la Terre. Son corps, agrandi de façon anormale, présente des muscles plus développés, une peau fissurée par des excroissances minérales, et des griffes épaisses capables de trancher la roche. Ses mâchoires, déformées par l''évolution de son régime cannibale, sont désormais adaptées à broyer la chair et les os.', 'Plaines, Forêts, Anciens champs de bataille', NULL, 'monstres', 'Bestiaire 2.0 › lignes 19084-19261');
