INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/jambieres-moisies', 'Jambières moisies', 'jambieres-moisies', 85, 'J', 'EP2', 2, 2, 'Les Jambières Moisies sont un spectre d’apparence inquiétante : deux jambières anciennes, fendues et rongées par la corrosion, flottant dans l’air comme si un corps invisible se tenait à l’intérieur. Le fantôme qui les anime est un voile d’un vert sombre, plus étroit et nerveux que celui des autres membres du cortège, n''apparaît de sa forme cauchemardesque que quand il attaque ou esquive. Ses contours vibrent légèrement, comme une ombre impatiente prête à bondir, et chaque mouvement laisse une traînée éthérée presque imperceptible.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/jambieres-moisies', 1, 'Ruines', 'ruines', 'monstres', 'Bestiaire 2.0 › lignes 19268-19326');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/jambieres-moisies', 2, 'Cimetière', 'cimetiere', 'monstres', 'Bestiaire 2.0 › lignes 19268-19326');
