INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/jambieres-moisies#carte:jambieres-moisies', 9, 'immunite', 'Immunité(s) Dégâts/Effets = 0', 'Poison, Maladie, Saignement, Peur, Fatigue', 'Bestiaire 2.0 › ligne 19311', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/jambieres-moisies#carte:jambieres-moisies', 10, 'capacites', 'Capacité(s)', 'Mourir peut attendre. Cette créature n’a que la moitié de sa santé qu’elle est censée avoir. Quand elle tombe en dessous de 0 santé, elle sombre dans une mort temporaire qui ne dure qu’un tour, à la fin de ce dernier, elle revient avec toute sa santé et barrière. La deuxième mort est fatale par contre.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/jambieres-moisies#carte:jambieres-moisies', 11, 'tactique', 'TACTIQUE COMBAT', 'Le tueur du Cortèse, son objectif est d’affaiblir tout en étant discret ou alors achevé les adversaires les plus affaiblis. Il est attiré par une proie affaiblie et se permettra d’arrêter un duel si il sent qu’un autre adversaire est sur le point de tomber.', 'Bestiaire 2.0 › ligne 19325', 'monstres');
INSERT INTO monstre_caracteristique (monstre_id, caracteristique_id, rang, valeur, origine, source_ref) VALUES ('monstres/jambieres-moisies#carte:jambieres-moisies', 'force', 1, 0, 'monstres', 'Bestiaire 2.0 › ligne 19293');
