INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 12, 'capacites', 'Capacité(s)', 'Haine mutuelle. Cette créature inflige un bonus +10 dégâts contre les Fenrirs mais ces derniers ont également le même bonus sur cette première.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 13, 'tactique', 'TACTIQUE COMBAT', 'Les versions supérieures sont plus résistantes et plus fortes que les démons de base. Prudence celà dit, il abusera de sa magie et améliora le plus possible ses alliés.', 'Bestiaire 2.0 › ligne 19844', 'monstres');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 1, NULL, NULL, 'Haine mutuelle', 'Cette créature inflige un bonus +10 dégâts contre les Fenrirs mais ces derniers ont également le même bonus sur cette première.', 'monstres', 'Bestiaire 2.0 › ligne 19808');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 2, NULL, NULL, 'Triumvirat instable fenrir', 'Cette créature est liée aux magies de la Foudre, Glace et Ombre et est capable d’utiliser ces magies selon son niveau. Mais les faiblesses aux altérations d’états s’en trouvent amplifiées.', 'monstres', 'Bestiaire 2.0 › ligne 19808');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/loup-garou#carte:loup-garou-superieur', 3, NULL, NULL, 'Bond', 'Cette créature est capable de faire un bond équivalent à sa vitesse x2 en échange de 3IC.', 'monstres', 'Bestiaire 2.0 › ligne 19808');
