INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/lumiphage', 'Lumiphage', 'lumiphage', 88, 'L', 'EP7', 7, 7, 'Un squelette émanant d''une lumière aveuglante que l''on retrouve dans les anciens sites de culte de la Lumière. Selon les rumeurs, se seraient d''anciens défenseurs de la Lumière parjures, suite à un dévouement trop prononcé pour Aurora. Ils auraient conclu un pacte mystérieux qui leur permet d''honorer malgré la mort et le manquement aux lois, de pourfendre le mal et de convertir les infidèles à la bonté de la Vierge Solaire.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/lumiphage', 1, 'Ruines', 'ruines', 'monstres', 'Bestiaire 2.0 › lignes 20034-20221');
