INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/lumiphage#carte:lumiphage-soldat', 3, NULL, NULL, 'Soin non-mort', 'Cette créature est capable de soigner ses alliés non-morts avec la magie de la lumière.', 'monstres', 'Bestiaire 2.0 › ligne 20080');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/lumiphage#carte:lumiphage-soldat', 4, NULL, NULL, 'Tome de Lumière lvl4', 'Permet à cette créature de lancer des sorts de la magie de la Lumière au niveau 4 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 20080');
