INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/main-blanche#carte:main-blanche', 6, 'competences', 'Compétence(s) secondaire(s)', '[Non métamorphosé] +10% dans toutes les compétences', 'Bestiaire 2.0 › ligne 20430', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/main-blanche#carte:main-blanche', 7, 'capacites', 'Capacité(s)', 'Calque amitié/amour. Cette créature est capable de calquer les capacités d’une créature que sa cible affectionne dans son cœur en se métamorphosant en cette dernière. La métamorphose cesse quand l’adversaire est dans le coma ou quand le métamorphe tombe en dessous de 50% de santé (elle copie les carac, compétences, don, race, classe, magie mais garde ses attributs)
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/main-blanche#carte:main-blanche', 8, 'tactique', 'TACTIQUE COMBAT', 'La main est une monstruosité qui se métamorphose quand elle a repéré sa proie, elle utilisera tous les avantages de sa métamorphose pour abattre sa cible (sans pour autant dépasser les limites, même si la métamorphose implique un utilisateur de sorts niveau 5 de puissance, la main ne pourra pas utiliser plus haut que le niveau 3). Ka laib a tendance à garder sa cible en vue et se concentre sur elle. En cas de danger, elle n’hésitera pas à fuir.', 'Bestiaire 2.0 › ligne 20443', 'monstres');
INSERT INTO monstre_attaque (monstre_id, rang, nom, texte, origine, source_ref) VALUES ('monstres/main-blanche#carte:main-blanche', 1, '[Non métamorphosé] Poing', '4d10 dégâts de frappe', 'monstres', 'Bestiaire 2.0 › ligne 20416');
INSERT INTO monstre_attaque (monstre_id, rang, nom, texte, origine, source_ref) VALUES ('monstres/main-blanche#carte:main-blanche', 2, '[Non métamorphosé] Magie brute', '4d10 dégâts neutre (coût 9 chakra)', 'monstres', 'Bestiaire 2.0 › ligne 20416');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/main-blanche#carte:main-blanche', 1, NULL, NULL, 'Calque amitié/amour', 'Cette créature est capable de calquer les capacités d’une créature que sa cible affectionne dans son cœur en se métamorphosant en cette dernière. La métamorphose cesse quand l’adversaire est dans le coma ou quand le métamorphe tombe en dessous de 50% de santé (elle copie les carac, compétences, don, race, classe, magie mais garde ses attributs)', 'monstres', 'Bestiaire 2.0 › ligne 20433');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/main-blanche#carte:main-blanche', 2, NULL, NULL, 'Super barrière', 'Cette créature possède une barrière qui correspond à son chakra.', 'monstres', 'Bestiaire 2.0 › ligne 20433');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/main-blanche#carte:main-blanche', 3, NULL, NULL, 'Attendrissement', 'En échange de 3IC, cette créature peut forcer le jet de fermeté à sa cible, si cette dernière rate, elle ne peut pas attaquer à son prochain tour. (recharge de 3 tours)', 'monstres', 'Bestiaire 2.0 › ligne 20433');
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/masse-empoisonneuse', 'Masse empoisonneuse', 'masse-empoisonneuse', 91, 'M', 'EP6', 6, 6, 'Abomination née de l’alchimie et de la nécromancie, cette créature serpentine au corps boursouflé crache des projectiles toxiques à très longue portée. Dotée de deux bras griffus terminés par des faux osseuses, elle lacère et empoisonne tout sur son passage. Son corps suinte un poison alchimique instable, rongeant la vie et la matière.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/masse-empoisonneuse', 1, 'Ruines', 'ruines', 'monstres', 'Bestiaire 2.0 › lignes 20446-20510');
