INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/molvacier#carte:molvacier-jeune', 12, 'tactique', 'TACTIQUE COMBAT', 'Ces grosses taupes sont capables de creuser de grandes galeries dans les montagnes et sont considérées comme nuisibles par les nains car leur passage peut entraîner des effondrement de galerie. Bien que craintif, elles peut se défendre avec ses griffes fait d’acier naturellement qui est capable de démolir des armures trop légère.', 'Bestiaire 2.0 › ligne 20573', 'monstres');
