INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/molvacier#carte:molvacier-alpha', 1, NULL, NULL, 'Aveugle naturel', 'Cette créature est naturellement aveugle, ce qui l''immunise de tous les effets, attaques ou altérations d’état lié à la vue. Cet aveuglement ne l’empêche pas de connaître son environnement et de savoir où sont ses ennemis, la Perception n’est donc pas endommagée.', 'monstres', 'Bestiaire 2.0 › ligne 20683');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/molvacier#carte:molvacier-alpha', 2, NULL, NULL, 'Fouisseur', 'Cette créature peut plonger dans le sol pour attaquer par le bas une autre, ça lui demande un tour complet pour pouvoir attaquer mais bénéficie d’un bonus de +5 dégâts quand l’attaque fait mouche.', 'monstres', 'Bestiaire 2.0 › ligne 20683');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/molvacier#carte:molvacier-alpha', 3, NULL, NULL, 'Perce muraille', 'L’attaque de cette créature perce 6 AP.', 'monstres', 'Bestiaire 2.0 › ligne 20683');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/molvacier#carte:molvacier-alpha', 4, NULL, NULL, 'Tremblement', 'Dans le sol, cette créature fait remuer le sol si fort qu’elle force un jet de stabilité à sa cible pour ne pas qu’elle tombe par terre.', 'monstres', 'Bestiaire 2.0 › ligne 20683');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/molvacier#carte:molvacier-alpha', 5, NULL, NULL, 'Lanceur de sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Explosion rocheuse, Fer raffiné, Fer foudroyant, Souffle électrique.', 'monstres', 'Bestiaire 2.0 › ligne 20683');
