INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/momie#carte:momie', 11, 'tactique', 'TACTIQUE COMBAT', 'Les momies sont des combattantes avec un matériel qui ne paye pas de mine à première vue mais ces dernières se défendent très bien avec en plus de leur accès à des sorts de l’espace/temps. Personne ne sait d’où leur vient ce savoir.
