INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/noye#carte:noye-corrosif', 10, 'capacites', 'Capacité(s)', 'Non-Mort. Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/noye#carte:noye-corrosif', 11, 'tactique', 'TACTIQUE COMBAT', 'L’acide de ce zombi est également présent dans ses dents et va l’infliger juste après son attaque de morsure.', 'Bestiaire 2.0 › ligne 21654', 'monstres');
