INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/noye#carte:noye-corrosif', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 21642');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/noye#carte:noye-corrosif', 2, NULL, NULL, 'Téméraire', 'Cette créature est toujours en offensif.', 'monstres', 'Bestiaire 2.0 › ligne 21642');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/noye#carte:noye-corrosif', 3, NULL, NULL, 'Vomi+', 'La créature vomi une espèce d’acide qui va s’infiltrer dans les armures ou vêtements et brûler la peau. Inflige pendant 2 tours 3d6 dégâts perce armure et va retirer un cran de solidité au morceau d’armure touché (une seule fois).', 'monstres', 'Bestiaire 2.0 › ligne 21642');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/noye#carte:noye-corrosif', 4, NULL, NULL, 'Croc vert', 'L’attaque de morsure de cette créature possède également la propriété du jet de vomi et l’inflige juste après l''attaque.', 'monstres', 'Bestiaire 2.0 › ligne 21642');
