INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/ogre#carte:ogre', 12, 'capacites', 'Capacité(s)', 'Haine mutuelle. Cette créature inflige un bonus +10 dégâts contre les Marcass mais ces derniers ont également le même bonus sur cette première.
