INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/ogre#carte:ogre-superieur', 13, 'tactique', 'TACTIQUE COMBAT', 'Comme tous les supérieurs des autres démons, ils sont plus puissants. Rien de plus à dire.', 'Bestiaire 2.0 › ligne 21938', 'monstres');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 1, NULL, NULL, 'Haine mutuelle', 'Cette créature inflige un bonus +10 dégâts contre les Marcass mais ces derniers ont également le même bonus sur cette première.', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 2, NULL, NULL, 'Pile ou Face', 'Cette créature dispose de deux façon de se battre, ce qui entraîne de gros changements dans la manière d''appréhender la créature. (Forme : Guerrier/Mage). La créature peut changer de forme au début ou en fin de tour gratuitement.
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 3, NULL, NULL, 'Tome 2 fois 2 couleurs', 'Cette créature dispose de 2 paires de magies qui utilise d’une façon qui lui est propre (voir Pile ou Face). Il utilisera les sorts qui correspondent à son niveau de puissance, il ne peut pas atteindre les sorts niveau 5 de puissance magique.', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 4, NULL, NULL, 'Recyclage', 'Manger de la viande avariée ou de mort redonne 2d8 santé.', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 5, '[EP2]', 2, 'Charge porcine', 'Permet d''avoir un bonus de +2 à la vitesse. Possible uniquement en ligne droite et si il y a une cible à l''arrivée.', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 6, '[EP3]', 3, 'Magie et Acier', '+3 aux dégâts des armes et des sorts.', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 7, '[EP4]', 4, 'Critique altérant', 'L’arme de cette créature, sur un coup critique, est capable d''obliger le jet de vigueur/fermeté pour ne pas que la cible prenne l’altération d’état liée à sa magie (aléatoire si elle en a plusieurs)', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 8, '[EP5]', 5, 'Nécrophage', 'Manger de la viande de cadavre redonne 3d8 barrière.', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 9, '[EP6]', 6, 'Face ou Face', 'L’ogre est capable d''activer temporairement ses deux têtes en même temps. Ce qui fait qu’elle combine tous les avantages en défense. Dure 3 tours. (1 fois par combat)', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 10, '[EP7]', 7, 'Phalange', 'L’arme de cette créature ignore l’effet des boucliers.', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 11, '[EP8]', 8, 'Météore', 'Permet de sauter sur une case et infliger -1d dégâts sur une zone de 3x3. (Portée = Vitesse)', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 12, '[EP9]', 9, 'Balayage', 'Permet de sacrifier 35% de réussite pour faire une attaque qui va toucher toutes les cibles autour (y compris en diagonale).', 'monstres', 'Bestiaire 2.0 › ligne 21897');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ogre#carte:ogre-superieur', 13, '[EP10]', 10, 'Surpuissance', 'Pendant le “Face et Face”, la créature obtient un bonus de +7 à tous les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 21897');
