INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/orc', 'Orc', 'orc', 98, 'O', 'EP1-10', 1, 10, 'L''Orc est la forme démoniaque et chaotique des Elfes forestiers, une mutation qui pousse leur agilité, leurs instincts et leur adaptation à un niveau démesuré. Son corps est celui d''un prédateur né pour la forêt : maigre, sec et doté de bras comme de jambes anormalement longs qui lui permettent de grimper avec une aisance déconcertante. Sa peau pâle, marbrée de nuances grises, verdâtres ou violacées, brise naturellement sa silhouette parmi les troncs et les feuillages. Son visage est la partie la plus troublante : une tête légèrement disproportionnée, d''immenses yeux aux pupilles extrêmement dilatables qui brillent dans l''obscurité, et une calvitie centrale bordée de longues mèches qui lui donnent une apparence immédiatement reconnaissable.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/orc', 1, 'Ici et là', 'ici-et-la', 'monstres', 'Bestiaire 2.0 › lignes 22085-22530');
