INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/presque-ottar', '“Presque-Ottar”', 'presque-ottar', 100, 'O', 'EP1 - 10', 1, 10, 'Le Presque-Ottar est une créature en pleine transition vers sa transformation totale en Ottar. Son apparence varie considérablement selon la ou les magies qui l’habitent : ses caractéristiques physiques, sa morphologie et même certaines parties de son corps peuvent changer selon qu’il est lié à une seule magie ou à deux. Dans tous les cas, ces influences magiques se manifestent sous une forme exagérée, difforme, voire grotesque, donnant naissance à une créature dont le corps semble incapable de contenir correctement le pouvoir qui l’habite.
