INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/presque-ottar#carte:presque-ottar', 11, 'capacites', 'Capacité(s)', 'Effondrement chakratique. Son chakra s’effondre et sa magie est hors de contrôle, cette créature obtient quatres dons selon si elle est mono magie ou bi-magie. Voir tableau plus bas.', 'Bestiaire 2.0 › ligne 22828', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/presque-ottar#carte:presque-ottar', 12, 'tactique', 'TACTIQUE COMBAT', 'Le presque Ottar n’est jamais le même selon les magies qui entrent dans un effondrement, il est nécessaire de bien connaître les magies et ce que ça peut impliquer.', 'Bestiaire 2.0 › ligne 22832', 'monstres');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/presque-ottar#carte:presque-ottar', 1, NULL, NULL, 'Effondrement chakratique', 'Son chakra s’effondre et sa magie est hors de contrôle, cette créature obtient quatres dons selon si elle est mono magie ou bi-magie. Voir tableau plus bas.', 'monstres', 'Bestiaire 2.0 › ligne 22828');
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-amoureux', 'Ottar Amoureux', 'ottar-amoureux', 101, 'O', 'EP1 - 10', 1, 10, 'Amalgame tragique de deux êtres dont l’amour a défié la mort : par un rituel inconnu, la chair du vivant s’est soudée à celle du disparu, ramenant une moitié à la vie au prix d’un effondrement chakratique. Ces siamois traquent implacablement les responsables de leur destin et toutes celles et ceux qui partagent leur histoire, cherchant à rayer ces noms de la mémoire collective.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-chariot', 'Ottar Chariot', 'ottar-chariot', 102, 'O', 'EP1 - 10', 1, 10, 'Géant de 3 à 4 mètres sans peau dans une armure de métal noir quasiment impénétrable, Chariot est un Ottar qui est très souvent utilisé comme machine de guerre pour poursuivre des cibles bien précise ou semer le trouble dans une ligne ennemi. Cadavre dont on a retiré entièrement la peau et forcé l''intégration de la magie du Sang et de la Nécromancie en même temps, cette créature souffre en permanence et poursuivra vie comme mort sur son chemin.
