INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 8, 'competences', 'Compétence(s) secondaire(s)', 'EP 1 - 3 : +10% Arme Lourde, +10% Stabilité, +10% Vigueur, +5% Intimidation
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 9, 'vulnerabilite', 'Vulnérabilité(s) Dégâts x2', '', 'Bestiaire 2.0 › ligne 23282', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 10, 'resistance', 'Résistance(s) Dégâts ÷2', '', 'Bestiaire 2.0 › ligne 23287', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 11, 'immunite', 'Immunité(s) Dégâts/Effets = 0', 'Peur, Couardise', 'Bestiaire 2.0 › ligne 23292', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 12, 'capacites', 'Capacité(s)', 'Ottar. Cette créature est un Ottar et est donc totalement invulnérable au contrôle mental, à la peur et à la couardise.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 13, 'tactique', 'TACTIQUE COMBAT', 'L’Ottar chariot est un monstre de force brute qui ne doit pas être sous-estimé, il dispose d’une bardiche géante capable de réduire en charpie beaucoup d''armures.Son armure est très solide et il est nécessaire de l’affaiblir avant de pouvoir prétendre lui faire des dégâts de manière convenable. Son absence d’attaque à distance fait que les attaquants physique et magique à distance peuvent affaiblir son armure mais prudence, son arme géante fait qu’il tape de plus loin qu’il n’y paraît.', 'Bestiaire 2.0 › ligne 23315', 'monstres');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 1, NULL, NULL, 'Ottar', 'Cette créature est un Ottar et est donc totalement invulnérable au contrôle mental, à la peur et à la couardise.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 3, NULL, NULL, 'Rempart solide', 'L’AP et l’AM de cette créature sont très élevés, pour affaiblir son armure, il faut réussir à le toucher avec un coup qui fait des dégâts supérieurs à sa valeur d’armure. Chaque coup réussi divisera par 2 ses AP et AM sur le morceau ciblé.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 4, NULL, NULL, 'Force démesurée', 'Cette créature peut dépasser la limite de Force de 1.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 5, NULL, NULL, 'Obscurité avantageuse', 'Cette créature est avantagée dans le noir, il impose un malus de 5% à tout les jets hostiles envers lui et toutes ses attaques font 1d de dégâts supplémantaire.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 6, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 23296');
INSERT INTO monstre_defense (monstre_id, sens, rang, cible, cible_cle, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 'immunite', 1, 'Peur', 'peur', 'monstres', 'Bestiaire 2.0 › ligne 23292');
INSERT INTO monstre_defense (monstre_id, sens, rang, cible, cible_cle, origine, source_ref) VALUES ('monstres/ottar-chariot#carte:ottar-chariot', 'immunite', 2, 'Couardise', 'couardise', 'monstres', 'Bestiaire 2.0 › ligne 23292');
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-diable', 'Ottar Diable', 'ottar-diable', 103, 'O', 'EP1 - 10', 1, 10, 'Un individu ayant été exposé simultanément à une quantité excessive de deux vapeurs issues de deux dimensions différentes et incompatibles. Leur présence simultanée dans son organisme provoque un effondrement chakratique unique, les deux influences entrant en conflit et se nourrissant mutuellement.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-etoile', 'Ottar Étoile', 'ottar-etoile', 104, 'O', 'EP1 - 10', 1, 10, 'Objet céleste déchu, l’Étoile n’existe que comme influence depuis le ciel. Son énergie violette, mystérieuse et corrosive, pousse les mortels à la folie et les incite à détruire tout ce qui contient du chakra. Les êtres touchés par son pouvoir deviennent ses prophètes, porteurs de la prophétie annonçant son retour.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-empereur', 'Ottar Empereur', 'ottar-empereur', 105, 'O', 'EP1 - 10', 1, 10, 'Créature exclusivement masculine née de dirigeants ou de guerriers dont l’ambition et la mégalomanie ont consumé l’esprit. L’Ottar Empereur surgit toujours dans les nations au faîte de leur puissance, quand leur dirigeant sombre dans l’obsession de la conquête.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-force', 'Ottar Force', 'ottar-force', 106, 'O', 'EP1 - 10', 1, 10, 'Obsession vivante de puissance brute, cet Ottar agit uniquement par instinct et par désir de démontrer sa supériorité. Sa force surhumaine et son endurance hors du commun le rendent presque impossible à arrêter, et il n’hésite pas à éliminer tout concurrent potentiel, même des enfants.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-fou', 'Ottar Fou', 'ottar-fou', 107, 'O', 'EP1 - 10', 1, 10, 'Être dont l’effondrement chakratique a détruit toute perception des règles régissant le monde, le Fou est une abomination imprévisible qui semble incapable de comprendre les notions de logique, de conséquence ou de limite. Son chakra refuse les lois auxquelles tous les autres êtres sont soumis, provoquant autour de lui des phénomènes impossibles et incohérents.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-grande-pretresse', 'Ottar Grande prêtresse', 'ottar-grande-pretresse', 108, 'O', 'EP1 - 10', 1, 10, 'Créature exclusivement féminine issue de prêtresses, croisées ou religieuses dont la foi ou la quête de savoir a implosé en un fanatisme absolu. Drapée de haillons religieux et d’un voile monstrueux couvert d''yeux et de glyphes vivants pour cacher son propre visage monstrueux, elle se croit l’incarnation d’une volonté divine.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-imperatrice', 'Ottar Impératrice', 'ottar-imperatrice', 109, 'O', 'EP1 - 10', 1, 10, 'Créature exclusivement féminine apparaissant chez une dirigeante, une mère ou une figure protectrice dont la compassion et l’empathie ont dépassé toute limite.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-isole', 'Ottar Isolé', 'ottar-isole', 110, 'O', 'EP1 - 10', 1, 10, 'L’Isolé est un Ottar profondément lié à un lieu qu’il considère comme son territoire. Propriétaire, gardien ou simple occupant, son obsession pour cet endroit est devenue si profonde que toute intrusion est perçue comme une menace existentielle. Lorsqu’il détecte un intrus, il se transforme en chasseur et le traque sans relâche, jusqu’à ce que celui-ci quitte son territoire ou soit détruit.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-justice', 'Ottar Justice', 'ottar-justice', 111, 'O', 'EP1 - 10', 1, 10, 'Figure d’une jeune femme aveugle portant une balance et une épée, l’Ottar Justice est né d’une personne dont l’obsession pour l’équité et le châtiment a fini par consumer toute raison. Pour elle, aucune faute ne peut rester impunie, aussi insignifiante soit-elle. Un mensonge, un vol, une insulte ou même une simple transgression de loi peuvent suffire à condamner quelqu’un à mort.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-jugement', 'Ottar Jugement', 'ottar-jugement', 112, 'O', 'EP1 - 10', 1, 10, 'Immense humanoïde dépourvu de visage et armé d’une gigantesque hache de bourreau, l’Ottar Jugement est une incarnation de la condamnation et de la fin. Nul ne sait qui il était avant son effondrement chakratique, son identité ayant totalement disparu derrière la fonction qu’il s’est imposée : être celui qui exécute le jugement.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-lune', 'Ottar Lune', 'ottar-lune', 113, 'O', 'EP1 - 10', 1, 10, 'L’Ottar Lune prend la forme d’une île mystérieuse et nomade, errant à travers les océans sans jamais suivre de trajectoire connue. L’île apparaît principalement aux marins égarés et les attire jusqu’à ses côtes, où ceux qui y échouent sont contraints de participer à d’étranges épreuves dont nul ne connaît véritablement la nature.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-magicien', 'Ottar Magicien', 'ottar-magicien', 114, 'O', 'EP1 - 10', 1, 10, 'Le Magicien est une créature humanoïde dont la peau semble faite de métal poli, parcourue de fissures lumineuses où le chakra bouillonne et s’échappe en pulsations constantes. Il est l’incarnation de la soif de puissance et de connaissance, d’une obsession qui a consumé son esprit. Ce sont généralement des individus qui ont cherché à dépasser les limites de leur chakra, à manipuler la magie dans toutes ses formes, ou à expérimenter sur eux-mêmes et le monde jusqu’à perdre toute raison.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-monde', 'Ottar Monde', 'ottar-monde', 115, 'O', 'EP1 - 10', 1, 10, 'Surnommé le « Divinicide », Monde est considéré comme l’Ottar le plus puissant jamais observé. Il représente une menace si considérable que même les Dieux craignent son apparition, car il serait capable de les tuer.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-mort', 'Ottar Mort', 'ottar-mort', 116, 'O', 'EP1 - 10', 1, 10, 'L’Ottar Mort apparaît lorsqu’un être confronté à la mort brutale d’un proche refuse d’accepter sa disparition et laisse sa haine prendre le dessus. Dans un rituel destiné à obtenir la puissance nécessaire pour accomplir sa vengeance, son chakra s’effondre et transforme son corps en une créature morte-vivante.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-pendu', 'Ottar Pendu', 'ottar-pendu', 117, 'O', 'EP1 - 10', 1, 10, 'Fusion tragique d’un être humanoïde et d’un arbre dégénéré, le Pendu semble immobile, suspendu dans un sommeil profond. Mais son chakra alimente la forêt qui s’étend autour de lui, ses racines et branches corrompues étouffant tout sur leur passage.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-roue-du-destin', 'Ottar Roue du Destin', 'ottar-roue-du-destin', 118, 'O', 'EP1 - 10', 1, 10, 'L’Ottar Roue du Destin se dissimule parmi les marchands, les voyageurs et les voyants, proposant ses services à ceux qui souhaitent connaître leur avenir. Ses prédictions sont d’une précision déconcertante, mais concernent généralement des événements sans grande importance : une rencontre heureuse, une bonne fortune ou au contraire une mésaventure sans conséquence.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-soleil', 'Ottar Soleil', 'ottar-soleil', 119, 'O', 'EP1 - 10', 1, 10, 'L’Ottar Soleil prend la forme d’un bâtiment banal apparaissant dans des lieux où une ou plusieurs personnes cherchent à s’abriter du froid, de la pluie ou de la neige. Il peut également apparaître au cœur même des villes, sans que personne ne remarque son arrivée. Son intérieur semble parfaitement accueillant : un feu crépite dans la cheminée, de la nourriture est disponible et tout est fait pour offrir à ses occupants un sentiment de sécurité et de confort.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-temperence', 'Ottar Tempérence', 'ottar-temperence', 120, 'O', 'EP1 - 10', 1, 10, 'Tempérance est une créature possédant deux âmes ou plus dans un même corps, plongée dans un conflit intérieur constant. Ce désaccord libère une énergie chaotique et incontrôlable, rendant la créature capable d’utiliser simultanément plusieurs magies. Au fil du temps, les différentes âmes modifient le corps de la créature : couleur de peau, corpulence et traits changent, traduisant visuellement le déséquilibre.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ottar-tour', 'Ottar Tour', 'ottar-tour', 121, 'O', 'EP1 - 10', 1, 10, 'Incarnation de l’effondrement, l’Ottar Tour n’est pas un simple être : c’est une abomination chakratique dégénérée, mi-machine, mi-organique, née de l’hubris des mortels. Plus qu’un adversaire, il est une catastrophe qui abat tout ce qui est érigé — villes, forteresses, nations.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/ours-garou', 'Ours-garou', 'ours-garou', 122, 'O', 'EP1 - 10', 1, 10, 'L’Ours-Garou est un démon, une abomination née d’une exposition prolongée au nuage de Kcirevam. Jadis un Orios, cette créature a été déformée, corrompue jusqu’à perdre toute raison. Sa musculature a doublé, sa fourrure s’est épaissie, et sa taille dépasse désormais celle des plus grands Orios. Sa tête, autrefois humanoïde, est devenue celle d’un ours monstrueux — symbole de la sauvagerie totale qui l’habite désormais.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/ours-garou', 1, 'Ici et là', 'ici-et-la', 'monstres', 'Bestiaire 2.0 › lignes 23490-23879');
