INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/ours-garou#carte:ours-garou-abominable', 13, 'tactique', 'TACTIQUE COMBAT', 'Les abominables sont des aberrations qui n’hésiterons pas à tuer tout être vivant sur leur chemin. Ils sont assez forts pour détruire des os entiers d’un seul coup, et ne doivent pas être sous-estimés.', 'Bestiaire 2.0 › ligne 23878', 'monstres');
