INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/pigeon-foudroyant', 'Pigeon foudroyant', 'pigeon-foudroyant', 123, 'P', 'EP1', 1, 1, 'Le Pigeon foudroyant s''est élevé au-dessus des autres columbiformes en transmettant ses habilités électrisantes à ses descendants. Les rumeurs parlent d''un pigeon ayant eu l''idée brillante d''entamer sa migration en passant au-dessus du Plateau Tonnerre. Évidemment, l''inévitable se produisit et la foudre a frappé le rat des cieux, mais contre toutes attentes : il survécu à l''impact. Après cet événement insolite, les pouvoirs de Volt l''envahirent et devint celui que l''on connaît aujourd''hui : un pigeon survolté près à surpasser sa réputation de nuisible.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/pigeon-foudroyant', 1, 'Ici et là', 'ici-et-la', 'monstres', 'Bestiaire 2.0 › lignes 23886-24062');
