INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/potironcier', 'Potironcier', 'potironcier', 126, 'P', 'EP5', 5, 5, 'Le Potironcier est une incarnation érudite des mystérieux Potimen, ces épouvantails animés à tête de potiron creusé dont l’intérieur brûle d’une flamme colorée. Son corps de paille est dissimulé sous une longue cape sombre qui ondule au vent des champs qu’il protège. À l’intérieur de sa tête blanche sculptée danse une flamme blanche éclatante, pure et stable, symbole de sa maîtrise de la magie de l’Arcane et de la Lumière.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/potironcier', 1, 'Champs', 'champs', 'monstres', 'Bestiaire 2.0 › lignes 24353-24489');
