INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 1, NULL, NULL, 'Folle de guerre', 'Cette créature doit avancer vers l’ennemi, elle ne peut pas attendre et est immunisée contre toutes formes de peur.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 3, NULL, NULL, 'Anti-magie', 'Cette créature est totalement immunisée à la magie.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 4, NULL, NULL, 'Aveugle naturel', 'Cette créature est naturellement aveugle, ce qui l''immunise de tous les effets, attaques ou altérations d’état lié à la vue. Cet aveuglement ne l’empêche pas de connaître son environnement et de savoir où sont ses ennemis, la Perception n’est donc pas endommagée.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 5, NULL, NULL, 'Son strident', 'Cette créature est capable de faire résonner un son strident sur tout le terrain qui va empêcher l’utilisation de la magie pendant 2 tours complets. (4 tours de recharge)', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 6, NULL, NULL, 'Vulnérabilité acide', 'Cette créature possède une vulnérabilité contre les dégâts d’acide, les sorts affligeants des dégâts d’acide ne sont pas annulés mais leur effets secondaires oui.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 7, NULL, NULL, 'Destruction', 'Le coup critique de cette créature retire automatiquement un cran de solidité à l’arme ou morceau d’armure.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 8, NULL, NULL, 'Inarrêtable', 'Cette créature ne peut être arrêtée dans son élan, seule une autre chose inarrêtable peut être utilisée pour l’arrêter.', 'monstres', 'Bestiaire 2.0 › ligne 24655');
INSERT INTO monstre_defense (monstre_id, sens, rang, cible, cible_cle, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 'vulnerabilite', 1, 'Acide', 'acide', 'monstres', 'Bestiaire 2.0 › ligne 24647');
INSERT INTO monstre_defense (monstre_id, sens, rang, cible, cible_cle, origine, source_ref) VALUES ('monstres/radrak-frenetique#carte:radrak-frenetique-sanguin', 'immunite', 1, 'Magie', 'magie', 'monstres', 'Bestiaire 2.0 › ligne 24651');
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/rat', 'Rat', 'rat', 128, 'R', 'EP1', 1, 1, 'Le Rat est une créature commune des ruelles, des souterrains et des champs abandonnés. Plus gros que les rongeurs ordinaires, il peut atteindre la taille d’un chien, avec un corps nerveux, un pelage terne et des incisives particulièrement développées. Individuellement faible et fragile, il mise sur la rapidité et le nombre pour survivre dans les environnements hostiles.
