INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/soldat-de-fer', 'Soldat de fer', 'soldat-de-fer', 132, 'S', 'EP4', 4, 4, 'Le Soldat de Fer est une abomination née des mystérieuses Terres Grises, au cœur du continent de Mrode. Son origine demeure incertaine, mais de nombreux érudits soupçonnent un cataclysme ancien mêlant la magie de la Terre et celle du Vide, fusionnant matière minérale et néant en une forme instable et hostile. Son corps est constitué d’un métal sombre et liquide, perpétuellement en mouvement, prenant une silhouette humanoïde lisse et sans visage, dépourvue de traits.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/soldat-de-fer', 1, 'Terres grises', 'terres-grises', 'monstres', 'Bestiaire 2.0 › lignes 25362-25538');
