INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/squelette', 'Squelette', 'squelette', 134, 'S', 'EP1', 1, 1, 'Les squelettes sont des serviteurs du mal animés par une énergie nécromantique. Leur ossature blanche, parfois maculée de restes de chair desséchée ou de chaînes rouillées, trahit leur origine morbide. Leur absence de conscience et de peur les pousse à affronter tout adversaire sans aucune retenue, mais leur carcasse fragile se fait très vite réduire en miettes par l’ennemi.', 'Ruines, Cimetière, Plaine, Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 25731-25972');
