INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-de-pierre#carte:squelette-de-roche', 5, NULL, NULL, 'Maladie de la Pierre', 'Quand cette créature fait un coup critique à l’attaque, il oblige un jet de vigueur à la cible, si cette dernière rate, elle prend “pétrification 1”. Si la victime fait un échec critique à son jet, elle contracte la Maladie de la Pierre.', 'monstres', 'Bestiaire 2.0 › ligne 26077');
