INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-determine', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 26511');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-determine', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 26511');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-determine', 3, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 26511');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-determine', 4, NULL, NULL, 'Résistance à la magie', 'Cette créature encaisse seulement la moitié des dégâts magiques.', 'monstres', 'Bestiaire 2.0 › ligne 26511');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-determine', 5, NULL, NULL, 'Tome de l’Ombre lvl5', 'Permet à cette créature de lancer des sorts de la magie de l’Ombre au niveau 5 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 26511');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-determine', 6, NULL, NULL, 'Tome de la Foudre lvl5', 'Permet à cette créature de lancer des sorts de la magie de la Foudre au niveau 5 de puissance.', 'monstres', 'Bestiaire 2.0 › ligne 26511');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-determine', 7, NULL, NULL, 'Général non-mort', 'Si d’autres non-mort sont présents sur le terrain et sont ses alliés : +6 dégâts et +1 Vitesse tant que la créature est en vie.', 'monstres', 'Bestiaire 2.0 › ligne 26511');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-mauvais#carte:squelette-mauvais-determine', 8, NULL, NULL, 'Climatosceptique', 'Cette créature ne prend aucun effet négatif de la météo.', 'monstres', 'Bestiaire 2.0 › ligne 26511');
