INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-toxique', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 26713');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-toxique', 2, NULL, NULL, 'Squelettique', 'Rend cette créature immunisé aux attaques d’estoc', 'monstres', 'Bestiaire 2.0 › ligne 26713');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-toxique', 3, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 26713');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-toxique', 4, NULL, NULL, 'Attaque poison', 'L’arme de la créature est capable d’empoisonnement. Chaque attaque va obliger un jet de vigueur à la victime, si elle rate, elle prend “Poison 1”.', 'monstres', 'Bestiaire 2.0 › ligne 26713');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-toxique', 5, NULL, NULL, 'Lanceur de sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Pieu d’os, Armure d’os.', 'monstres', 'Bestiaire 2.0 › ligne 26713');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-toxique', 6, NULL, NULL, 'Double attaque', 'Cette créature possède deux armes et peut les utiliser en ambidextrie (avec les malus réduit à 10% et 20% pour les attaques)', 'monstres', 'Bestiaire 2.0 › ligne 26713');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/squelette-venin#carte:squelette-toxique', 7, NULL, NULL, 'Pandémie', 'Quand un ennemi passe à côté de ses alliés alors qu’il souffre d’un poison, son allié est forcé de faire un jet de vigueur pour ne pas prendre le poison.', 'monstres', 'Bestiaire 2.0 › ligne 26713');
