INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue-superieur', 3, NULL, NULL, 'Pics évolutifs', 'Cette créature est couverte de pics sur son corps qui ne font que grandir au fur et à mesure du temps. Chaque début de tour, la créature cumule +1AP/AM tant que ses pics sont présents (maximum 5 tours). Au bout de 3 tours elle peut les relâcher dans une attaque en cône de 6 de portée, elles infligent 5 dégâts d’estoc multiplié par le nombre de tour cumulé.', 'monstres', 'Bestiaire 2.0 › ligne 26949');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue-superieur', 4, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 26949');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue-superieur', 5, '[EP2]', 2, 'Souffle élémentaire', 'Cette créature est capable de cracher un souffle lié à son élément. Ce souffle est capable d''infliger l''altération d''état lié à l''élément à hauteur de 35% de chance de l''infliger. (les joueurs doivent faire les jets en conséquence pour ne pas prendre l''altération d''état).', 'monstres', 'Bestiaire 2.0 › ligne 26949');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue-superieur', 6, '[EP3]', 3, 'Humidification', 'Dispose d''une protection qui vont ignorer les 10 premiers dégâts qui vont lui être infligés lors d''un combat (se recharge tous les 3 tours)', 'monstres', 'Bestiaire 2.0 › ligne 26949');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue-superieur', 7, '[EP4]', 4, 'Pics solide', 'Les pics donnent +2AP/AM au lieu de 1.', 'monstres', 'Bestiaire 2.0 › ligne 26949');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue-superieur', 8, '[EP5]', 5, 'Pics élémentaires', 'Les pics peuvent infliger des dégâts élémentaires liés à la magie de la créature.', 'monstres', 'Bestiaire 2.0 › ligne 26949');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:velue-superieur', 9, '[EP6]', 6, 'Super pics', 'Les dégâts de pics évolutifs passent à 10.', 'monstres', 'Bestiaire 2.0 › ligne 26949');
