INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/velue#carte:vouivre-squelette', 10, 'capacites', 'Capacité(s)', 'Non-Mort. Une créature non-mort est dépourvue de morale et d''émotion ce qu''il l''a rendue immunisée aux sorts mentaux ainsi qu''une immunité contre le poison et la maladie. Elle bénéficie également d''un bonus de +60 pour l''intimidation. Sa volonté est à 9 (les jets de vigueur/fermeté contre des effets de magie dont il est vulnérable divise par 2 les chances de les réussir).
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/velue#carte:vouivre-squelette', 11, 'tactique', 'TACTIQUE COMBAT', 'Ces anciennes vouivres ont conservé leur puissance et restent particulièrement dangereuses même si elles ne peuvent plus faire de souffle élémentaire. Elles vont attaquer violemment le plus de cible possible.', 'Bestiaire 2.0 › ligne 27257', 'monstres');
