INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 9, 'immunite', 'Immunité(s) Dégâts/Effets = 0', 'Poison, Maladie, Enragé, Peur, Aveuglement, Confusion, Fatigue, Saignement, Surdité, Estoc', 'Bestiaire 2.0 › ligne 27301', 'monstres');
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 10, 'capacites', 'Capacité(s)', 'Non-Mort. Une créature non-mort est dépourvue de morale et d''émotion ce qu''il l''a rendue immunisée aux sorts mentaux ainsi qu''une immunité contre le poison et la maladie. Elle bénéficie également d''un bonus de +60 pour l''intimidation. Sa volonté est à 9 (les jets de vigueur/fermeté contre des effets de magie dont il est vulnérable divise par 2 les chances de les réussir).
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 11, 'tactique', 'TACTIQUE COMBAT', 'Ces vouivres cherchent à démoraliser l''ennemi le plus possible, ils vont chercher à ce que tous les ennemis possèdent l’état Peur.', 'Bestiaire 2.0 › ligne 27325', 'monstres');
