INSERT INTO monstre_attaque (monstre_id, rang, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 3, 'Cri terrifiant', '6d10 dégâts sonore + 10 (“Peur 1” si jet de prouesse raté)', 'monstres', 'Bestiaire 2.0 › ligne 27272');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est dépourvue de morale et d''émotion ce qu''il l''a rendue immunisée aux sorts mentaux ainsi qu''une immunité contre le poison et la maladie. Elle bénéficie également d''un bonus de +60 pour l''intimidation. Sa volonté est à 9 (les jets de vigueur/fermeté contre des effets de magie dont il est vulnérable divise par 2 les chances de les réussir).', 'monstres', 'Bestiaire 2.0 › ligne 27305');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 2, NULL, NULL, 'Grande créature', 'Cette créature est bien plus grande que les autres, ainsi les malus de visée des ennemis sont réduits de moitié. Chaque attaque physique prodiguée par la créature force un jet de stabilité pour ne pas être repoussé de 1d4 cases en arrière et tomber au sol.', 'monstres', 'Bestiaire 2.0 › ligne 27305');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 3, NULL, NULL, 'Squelettique', 'Rend cette créature immunisé aux attaques d’estoc', 'monstres', 'Bestiaire 2.0 › ligne 27305');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 4, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 27305');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 5, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 27305');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 6, NULL, NULL, 'Résistance à la magie', 'Cette créature encaisse seulement la moitié des dégâts magiques.', 'monstres', 'Bestiaire 2.0 › ligne 27305');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:grande-vouivre-squelette', 7, NULL, NULL, 'Cri mortuaire', 'Quand les ennemis qui encaisse le cri terrifiant tentent le jet de prouesse, ils ont un malus de 20% au jet.', 'monstres', 'Bestiaire 2.0 › ligne 27305');
