INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:vouivre-squelette-ancienne', 4, NULL, NULL, 'Charge sans peur', 'Permet d''avoir un bonus de +7 au jet d''initiative.', 'monstres', 'Bestiaire 2.0 › ligne 27373');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:vouivre-squelette-ancienne', 5, NULL, NULL, 'Vol', 'Cette créature est capable de voler et donc d’ignorer les terrains négatifs.', 'monstres', 'Bestiaire 2.0 › ligne 27373');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:vouivre-squelette-ancienne', 6, NULL, NULL, 'Résistance à la magie', 'Cette créature encaisse seulement la moitié des dégâts magiques.', 'monstres', 'Bestiaire 2.0 › ligne 27373');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:vouivre-squelette-ancienne', 7, NULL, NULL, 'Cri mortuaire', 'Quand les ennemis qui encaisse le cri terrifiant tentent le jet de prouesse, ils ont un malus de 20% au jet.', 'monstres', 'Bestiaire 2.0 › ligne 27373');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/velue#carte:vouivre-squelette-ancienne', 8, NULL, NULL, 'Cri universel', 'Cette créature est capable d’utiliser tous les cris qui existent dans les différentes magies (utilise de la santé pour utiliser les cris magiques)', 'monstres', 'Bestiaire 2.0 › ligne 27373');
