INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/voromorphe', 'Voromorphe', 'voromorphe', 140, 'V', 'EP5', 5, 5, 'Le Voromorphe est une créature carnivore, considérée comme l’un des prédateurs a ne pas sous-estimé. Sa particularité – et la source de son appellation – réside dans sa capacité d’adaptation élémentaire. Contrairement aux autres monstres liés à un seul élément, le Voromorphe assimile l’essence du milieu où il vit et s’y adapte totalement, jusqu’à métamorphoser son corps. Cette adaptation n’est pas instantanée, il lui faut plusieurs mois pour réussir à changer son corps, ce lap de temps rend la créature assez vulnérable, d’où son changement de comportement où il se fait plus discret le temps qu’il faut.
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/voromorphe', 1, 'Ici et là', 'ici-et-la', 'monstres', 'Bestiaire 2.0 › lignes 27483-27681');
