INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/voromorphe#carte:voromorphe-jeune', 10, 'tactique', 'TACTIQUE COMBAT', 'Le Voromorphe est une créature assez imprévisible à cause de sa capacité à s’adapter à son environnement, un voromorphe du feu sera différent de celui de la terre, etc … Il faut savoir faire preuve de souplesse avec cette créature pour ne pas être surpris.', 'Bestiaire 2.0 › ligne 27549', 'monstres');
