INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/voromorphe#carte:voromorphe-apex', 10, 'tactique', 'TACTIQUE COMBAT', 'Celui qu’on appelle “apex” est le voromorphe qui a su s’imposer sur son territoire qu’aucune créature ne tente sa chance pour le prédater. Il dispose d’une immunité à l’élément de son environnement et fait des ravages contre les pauvres caravanes qui ont le malheur de passer sur son territoire quand il chasse.', 'Bestiaire 2.0 › ligne 27680', 'monstres');
