INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/zombi-soldat#carte:zombi-sergent', 10, 'capacites', 'Capacité(s)', 'Non-Mort. Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/zombi-soldat#carte:zombi-sergent', 11, 'tactique', 'TACTIQUE COMBAT', 'La version sergent du zombi soldat est celui qui arrive à inspirer les autres, il est capable de les rendre plus fort et plus vif au combat, en plus d’être lui-même plus puissant.', 'Bestiaire 2.0 › ligne 27987', 'monstres');
