INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zombi-soldat#carte:zombi-sergent', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 27972');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zombi-soldat#carte:zombi-sergent', 2, NULL, NULL, 'Téméraire', 'Cette créature est toujours en offensive et ne possède pas le malus pour toucher sa cible.', 'monstres', 'Bestiaire 2.0 › ligne 27972');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zombi-soldat#carte:zombi-sergent', 3, NULL, NULL, 'Frappe poison', 'L’arme de la créature possède une chance d’empoisonnement. Chaque attaque a 25% de chance d’obliger un jet de vigueur à la victime, si elle rate, elle prend “Poison 1”.', 'monstres', 'Bestiaire 2.0 › ligne 27972');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zombi-soldat#carte:zombi-sergent', 4, NULL, NULL, 'Intervention', 'Cette créature est capable de prendre un coup à la place d''un allié si il est à côté de lui.', 'monstres', 'Bestiaire 2.0 › ligne 27972');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zombi-soldat#carte:zombi-sergent', 5, NULL, NULL, 'Chef non-mort', 'Si d’autres non-mort sont présents sur le terrain et sont ses alliés : +4 dégâts et +2 Initiative tant que la créature est en vie (non cumulable).', 'monstres', 'Bestiaire 2.0 › ligne 27972');
