INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zombinox#carte:zombinox-iii', 1, NULL, NULL, 'Non-Mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'monstres', 'Bestiaire 2.0 › ligne 28193');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zombinox#carte:zombinox-iii', 2, NULL, NULL, 'Super santé', 'Cette créature possède le double de santé.', 'monstres', 'Bestiaire 2.0 › ligne 28193');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zombinox#carte:zombinox-iii', 3, NULL, NULL, 'Crache chakra+', 'Tous les 10% de santé perdu, cette créature libère “Boule de chakra” sur tous les ennemis sur le terrain, ce sort va infliger 7d6 dégâts magiques (comme si elle était surchargé)', 'monstres', 'Bestiaire 2.0 › ligne 28193');
INSERT INTO monstre_capacite (monstre_id, rang, prefixe, ep_min, nom, texte, origine, source_ref) VALUES ('monstres/zombinox#carte:zombinox-iii', 4, NULL, NULL, 'Tu ne passe pas', 'Permet de bloquer les adversaires dans sa zone d’influence complète. Permet également d’intercepter les attaques avec un jet de défense réussi.', 'monstres', 'Bestiaire 2.0 › ligne 28193');
