INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref) VALUES ('monstres/zompi', 'Zompi', 'zompi', 144, 'Z', 'EP3', 3, 3, 'Le Zompi est un cadavre réanimé par un champignon parasite d’origine inconnue. Ce dernier s’empare du système nerveux et musculaire de son hôte mort, le faisant bouger avec des gestes saccadés, comme tiré par des fils invisibles. Le champignon prolifère à travers le corps en formant des excroissances mycosiques : des chapeaux difformes, des amas de spores sur le dos, et des filaments qui s’échappent des yeux, de la bouche ou des plaies ouvertes. Sa peau en décomposition est percée de racines fongiques qui le maintiennent debout bien après la mort.', 'Marais, Ruines', NULL, 'monstres', 'Bestiaire 2.0 › lignes 28213-28407');
INSERT INTO monstre_espece_lieu (espece_id, rang, lieu, lieu_cle, origine, source_ref) VALUES ('monstres/zompi', 1, 'Marais', 'marais', 'monstres', 'Bestiaire 2.0 › lignes 28213-28407');
