INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/zompi#carte:zompi', 11, 'tactique', 'TACTIQUE COMBAT', 'Le zompi est un non-mort infecté par un champignon qui se trouve directement dans son cerveau. Son objectif est de répandre le plus possible ses spores dans le corps de ses victimes. Il ne faut pas essayer de l’affronter de face pour les aventuriers avec une vigueur faible sous peine de voir ses capacités de combat réduite.', 'Bestiaire 2.0 › ligne 28273', 'monstres');
