INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/zompi#carte:zompiceps', 10, 'capacites', 'Capacité(s)', 'Non-Mort. Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.
INSERT INTO monstre_rubrique (monstre_id, rang, rubrique, titre, texte, source_ref, origine) VALUES ('monstres/zompi#carte:zompiceps', 11, 'tactique', 'TACTIQUE COMBAT', 'Le champignon a atteint son stade final et enveloppe complètement son hôte à tel point qu’on pourrait croire que c’est un champignon en forme d’humanoïde. Il est très massif et utilise ses poings pour détruire la vie qui se trouve sur son chemin, il ne possède plus de tête donc aucun point faible apparent. Le champignon est tellement développé que ça lui donne une armure très difficile à pénétrer.', 'Bestiaire 2.0 › ligne 28406', 'monstres');
INSERT INTO monstre_caracteristique (monstre_id, caracteristique_id, rang, valeur, origine, source_ref) VALUES ('monstres/zompi#carte:zompiceps', 'force', 1, 6, 'monstres', 'Bestiaire 2.0 › ligne 28361');
